local function extract_thought_href(value,seen,depth)
    if depth>4 or value==nil then return nil end
    if type(value)=="string" then return value:match("(#?miuthought%-[%x%.]+)") end
    if type(value)~="table" then return nil end
    seen=seen or {}; if seen[value] then return nil end; seen[value]=true
    for _,key in ipairs({"href","url","target","link","uri","dest","destination"}) do local found=extract_thought_href(value[key],seen,depth+1); if found then return found end end
    for _,child in pairs(value) do local found=extract_thought_href(child,seen,depth+1); if found then return found end end
end
function Plugin:_teardown_thought_tap()
    if self._thought_tap_setup and self.ui and self.ui.unRegisterTouchZones then pcall(function() self.ui:unRegisterTouchZones({{id="miuread_thought_popup",overrides={"tap_link"}}}) end) end
    self._thought_tap_setup=nil
end
function Plugin:_thought_font_size(value)
    -- The native comment popup uses this same final size for layout metrics and
    -- glyph rendering. The popup explicitly uses ThoughtFaceFactory:getFinalFace()
    -- so the device scale is applied exactly once. UI preview callers stay logical.
    local logical
    if tonumber(value) then logical=math.max(12,math.min(48,math.floor(tonumber(value)+.5)))
    else
        local legacy={small=18,standard=22,large=26,xlarge=30}
        logical=legacy[tostring(value or "standard")] or 22
    end
    local scaled=logical
    if Device and Device.screen and type(Device.screen.scaleBySize)=="function" then
        local ok,result=pcall(Device.screen.scaleBySize,Device.screen,logical)
        if ok and tonumber(result) then scaled=math.max(logical,math.floor(tonumber(result)+.5)) end
    end
    return scaled
end

local function usable_font_name(value)
    if type(value)~="string" then return nil end
    value=value:match("^%s*(.-)%s*$")
    if value=="" then return nil end
    return value
end
function Plugin:_thought_font_name(prefs)
    prefs=prefs or (self.store:preferences().thoughts or {})
    if prefs.follow_body_font~=true then
        return usable_font_name(prefs.font_face)
    end
    local doc=self.ui and self.ui.document
    if doc and type(doc.getFontFace)=="function" then
        local ok,value=pcall(doc.getFontFace,doc)
        if ok then
            name=usable_font_name(value)
            if name then return name end
        end
    end

    local name=usable_font_name(self.ui and self.ui.font and self.ui.font.font_face)
    if name then return name end

    if _G.G_reader_settings and type(_G.G_reader_settings.readSetting)=="function" then
        local ok,value=pcall(_G.G_reader_settings.readSetting,_G.G_reader_settings,"cre_font")
        if ok then return usable_font_name(value) end
    end
    return nil
end
function Plugin:_write_thought_popup_marker(stage, info, extra)
    local path=tostring(self._thought_popup_marker_path or "")
    if path=="" then return false end
    local payload={
        version=tostring(self.version or Config.VERSION),
        stage=tostring(stage or "unknown"),
        timestamp=os.time(),
        book_id=info and tostring(info.book_id or "") or nil,
        chapter_uid=info and tostring(info.chapter_uid or "") or nil,
        range=info and tostring(info.range or "") or nil,
    }
    for key,value in pairs(type(extra)=="table" and extra or {}) do payload[key]=value end
    local ok,encoded=pcall(Json.encode,payload)
    if not ok then return false end
    return U.atomic_write(path,encoded,true)==true
end

function Plugin:_clear_thought_popup_marker()
    local path=tostring(self._thought_popup_marker_path or "")
    if path~="" then os.remove(path) end
end

function Plugin:_flush_reader_checkpoint(reason, force)
    if not (self.ui and self.ui.document) then return false end
    -- KOReader already saves the current reading position during its own
    -- suspend/close lifecycle. MiuRead only needs an additional full settings
    -- flush when annotations or document settings actually changed. Avoiding a
    -- redundant save removes the most visible lock/close pause.
    if self._reader_checkpoint_dirty~=true and force~=true then
        logger.dbg("[MiuRead][ReaderCheckpoint] clean; extra save skipped","reason=",tostring(reason or "unspecified"))
        return true
    end
    local now=os.time()
    if force~=true and now-(tonumber(self._reader_checkpoint_last) or 0)<1 then return true end
    local ok,err=xpcall(function()
        if type(self.ui.saveSettings)=="function" then
            self.ui:saveSettings()
        elseif type(self.ui.handleEvent)=="function" then
            self.ui:handleEvent(Event:new("SaveSettings"))
            if self.ui.doc_settings and type(self.ui.doc_settings.flush)=="function" then
                self.ui.doc_settings:flush()
            end
        end
    end,debug.traceback)
    if ok then
        self._reader_checkpoint_last=now
        self._reader_checkpoint_dirty=false
        logger.info("[MiuRead][ReaderCheckpoint] saved","reason=",tostring(reason or "unspecified"))
        return true
    end
    logger.warn("[MiuRead][ReaderCheckpoint] save failed","reason=",tostring(reason or "unspecified"),tostring(err))
    return false
end

function Plugin:_schedule_reader_checkpoint(reason, delay)
    if not (self.ui and self.ui.document) then return false end
    if self._reader_checkpoint_task then
        UIManager:unschedule(self._reader_checkpoint_task)
        self._reader_checkpoint_task=nil
    end
    local task
    task=function()
        if self._reader_checkpoint_task~=task then return end
        self._reader_checkpoint_task=nil
        self:_flush_reader_checkpoint(reason,false)
    end
    self._reader_checkpoint_task=task
    UIManager:scheduleIn(math.max(.2,tonumber(delay) or 2.0),task)
    return true
end

function Plugin:_finish_thought_popup(generation)
    if generation and generation~=self._thought_popup_generation then return end
    self._thought_popup=nil
    self._thought_popup_busy=false
    self:_clear_thought_popup_marker()
    if self.download_task then self.download_task:resume("thought_popup") end
    self:_mark_reader_busy(2)
    if self._performance_prompt_pending then
        UIManager:scheduleIn(.45,function() self:_show_performance_prompt() end)
    end
    UIManager:scheduleIn(1.2,function() collectgarbage("step",48) end)
end

function Plugin:_cancel_thought_prewarm(reason)
    self._thought_prewarm_generation=(tonumber(self._thought_prewarm_generation) or 0)+1
    if self._thought_prewarm_task then
        UIManager:unschedule(self._thought_prewarm_task)
        self._thought_prewarm_task=nil
    end
    if self.thought_async and self.thought_async:busy() then
        self.thought_async:cancel(reason or "thought prewarm cancelled")
    end
end

function Plugin:_schedule_thought_prewarm()
    if self._thought_prewarm_task then
        UIManager:unschedule(self._thought_prewarm_task)
        self._thought_prewarm_task=nil
    end
    self._thought_prewarm_generation=(tonumber(self._thought_prewarm_generation) or 0)+1
    local generation=self._thought_prewarm_generation
    local task
    task=function()
        if self._thought_prewarm_task~=task or generation~=self._thought_prewarm_generation then return end
        self._thought_prewarm_task=nil
        if not self:_thoughts_enabled() or not self:_active_reader_ui()
            or self._miuread_suspended==true or HOME_SESSION.suspended==true
            or PowerState.state()~="NORMAL" or self._thought_popup_busy or self._thought_popup
            or RuntimePressure.active() then return end
        if self.download_task and self.download_task:busy() then return end
        if (tonumber(self._reader_busy_until) or 0)>os.time() then return end
        if not self.thought_async or not self.thought_async:available() or self.thought_async:busy() then return end
        local current=self.sync and self.sync.current or nil
        local book_id=tostring(current and current.book and current.book.book_id or "")
        if book_id=="" then return end
        local ok,position=pcall(self.sync.local_position,self.sync)
        local chapter_uid=ok and type(position)=="table" and tostring(position.chapter_uid or "") or ""
        if chapter_uid=="" then return end
        local key=book_id.."|"..chapter_uid
        if self._thought_prewarm_key==key then return end
        local limit=math.max(1,math.min(12,tonumber(Config.THOUGHT_PREWARM_GROUPS) or 6))
        local store=self.store
        local started,err=self.thought_async:run("thought-prewarm",function()
            local DB=require("miuread.thought_database")
            local value,db_err=DB.prewarm_chapter(store,book_id,chapter_uid,limit)
            if not value then error(tostring(db_err or "thought_prewarm_failed")) end
            return value
        end,function(result)
            if generation~=self._thought_prewarm_generation or not self:_active_reader_ui()
                or self._miuread_suspended==true or HOME_SESSION.suspended==true
                or PowerState.state()~="NORMAL" then return end
            if not result or result.ok~=true or type(result.value)~="table" then
                logger.warn("[MiuRead][ThoughtPrewarm] failed",
                    "book=",book_id,"chapter=",chapter_uid,
                    "error=",tostring(result and result.error or "unknown"))
                return
            end
            local groups=type(result.value.groups)=="table" and result.value.groups or {}
            local warmed,comments=Thoughts.prewarm_groups(self.store,book_id,chapter_uid,groups)
            self._thought_prewarm_key=key
            logger.info("[MiuRead][ThoughtPrewarm] ready",
                "book=",book_id,"chapter=",chapter_uid,
                "groups=",tostring(warmed),"comments=",tostring(comments))
        end,20)
        if not started then
            logger.warn("[MiuRead][ThoughtPrewarm] worker unavailable",tostring(err or "unknown"))
        end
    end
    self._thought_prewarm_task=task
    UIManager:scheduleIn(math.max(1.8,tonumber(Config.THOUGHT_PREWARM_DELAY) or 2.8),task)
end

function Plugin:_close_active_thought_popup(reason)
    local popup=self._thought_popup
    self._thought_popup_generation=(tonumber(self._thought_popup_generation) or 0)+1
    self._thought_popup=nil
    self._thought_popup_busy=false
    self:_clear_thought_popup_marker()
    if self.download_task then self.download_task:resume("thought_popup") end
    if popup and popup~=true then
        pcall(UIManager.close,UIManager,popup)
        logger.info("[MiuRead][ThoughtPopup] closed","reason=",tostring(reason or "forced"))
    end
end

function Plugin:_open_thought_info(info,generation)
    if generation~=self._thought_popup_generation or not (self.ui and self.ui.document) then
        self:_finish_thought_popup(generation)
        return
    end
    local started=monotonic_wall_time()
    local popup,notice
    local ok,unexpected=xpcall(function()
        -- The tap marker already proves a popup was active if KOReader exits
        -- abnormally. Keep intermediate stages in the log instead of rewriting
        -- the same flash file several times during one visible tap.
        local lookup_started=monotonic_wall_time()
        local group,err,token=Thoughts.find(self.store,info.book_id,info.chapter_uid,info.range)
        local lookup_ms=math.floor((monotonic_wall_time()-lookup_started)*1000+.5)
        if not group then notice=tostring(err or "没有想法内容"); return end
        local prefs=self.store:preferences().thoughts or {}
        local function on_close() self:_finish_thought_popup(generation) end
        local parts_started=monotonic_wall_time()
        local source,comments,count,native_cache_hit,native_signature=Thoughts.native_parts_cached(
            self.store,info.book_id,info.chapter_uid,info.range,group,token
        )
        local parts_ms=math.floor((monotonic_wall_time()-parts_started)*1000+.5)
        if tostring(source or "")=="" and #(comments or {})==0 then notice="没有想法内容"; return end
        local show_started=monotonic_wall_time()
        popup=ThoughtNativePopup.show{
            source_text=source,
            comments=comments,
            cache_key=table.concat({
                tostring(info.book_id or ""), tostring(info.chapter_uid or ""),
                tostring(info.range or ""), tostring(native_signature or ""),
            }, "|"),
            font_size=self:_thought_font_size(self:_thought_font_size_value(prefs)),
            font_name=self:_thought_font_name(prefs),
            width_ratio=tonumber(prefs.width_ratio) or 0.91,
            height_ratio=tonumber(prefs.height_ratio) or 0.55,
            on_close=on_close,
            on_interact=function() self:_mark_reader_busy(30) end,
            on_error=function()
                self:info("评论显示失败，窗口已安全关闭。当前阅读位置不会丢失。")
            end,
        }
        local show_ms=math.floor((monotonic_wall_time()-show_started)*1000+.5)
        local elapsed_ms=math.floor((monotonic_wall_time()-started)*1000+.5)
        logger.info("[MiuRead][ThoughtPopup] opened",
            "mode=","native_rounded_paged_swipe",
            "book=",tostring(info.book_id),"chapter=",tostring(info.chapter_uid),
            "comments=",tostring(count or 0),
            "source=",token and token.index_hit and "compact_index" or "chapter_cache",
            "cache=",token and token.cache_hit and "hit" or "miss",
            "native_cache=",native_cache_hit and "hit" or "miss",
            "lookup_ms=",tostring(lookup_ms),
            "parts_ms=",tostring(parts_ms),
            "show_ms=",tostring(show_ms),
            "elapsed_ms=",tostring(elapsed_ms))
        if not popup then error("评论窗口未能加入界面") end
        self._thought_popup=popup
        self:_record_performance("thought_popup",elapsed_ms)
        if token and token.index_hit~=true then
            UIManager:scheduleIn(.2,function() self:_schedule_current_book_repair_check(nil,true) end)
        end
    end,debug.traceback)
    if not ok then
        logger.err("[MiuRead][ThoughtPopup] open failed",tostring(unexpected))
        self:_finish_thought_popup(generation)
        self:info("评论暂时无法显示。当前阅读批注已先保存，请稍后重试。")
    elseif not popup then
        self:_finish_thought_popup(generation)
        if notice then self:info(notice) end
    end
end

function Plugin:_show_thought_href(href)
    local info=Thoughts.parse_href(href); if not info then return false end
    -- A disabled comment layer still owns its internal links. Consume them
    -- silently instead of letting KOReader report #miuthought as invalid.
    if not self:_thoughts_enabled() then return true end
    if self._thought_popup_busy or self._thought_popup then return true end
    local runtime=self._download_runtime
    if runtime and self.download_task and self.download_task:busy() and runtime.comment_slow_notice~=true then
        runtime.comment_slow_notice=true
        self:status_toast("后台正在下载","评论打开和翻页可能稍慢",3)
    end
    self._thought_popup_generation=(tonumber(self._thought_popup_generation) or 0)+1
    local generation=self._thought_popup_generation
    self._thought_popup_busy=true
    self:_write_thought_popup_marker("tap",info)
    if self.download_task then self.download_task:pause("thought_popup") end
    self:_mark_reader_busy(30)
    -- Only write document metadata here when annotations really changed.
    -- Repeatedly opening comments must not force a storage flush every time.
    if self._reader_checkpoint_dirty and os.time()-(tonumber(self._reader_checkpoint_last) or 0)>=5 then
        self:_flush_reader_checkpoint("before_thought_popup",false)
    end
    UIManager:nextTick(function()
        self:_open_thought_info(info,generation)
    end)
    return true
end

function Plugin:_thought_edge_page_turn(ges)
    local enabled,percent=self:_reader_edge_guard_state()
    if not enabled then return false end
    local pos=ges and ges.pos
    local x=pos and tonumber(pos.x)
    local width=Device.screen and Device.screen:getWidth()
    if not x or not width or width<=0 then return false end

    local ratio=math.max(.10,math.min(.30,(tonumber(percent) or 15)/100))
    local inverse=self.ui and self.ui.view and self.ui.view.inverse_reading_order==true
    local diff
    if x<=width*ratio then
        diff=inverse and 1 or -1
    elseif x>=width*(1-ratio) then
        diff=inverse and -1 or 1
    else
        return false
    end

    -- Keep KOReader's own tap-turn preference authoritative. The guard only
    -- resolves a collision between an edge annotation link and a page turn.
    if _G.G_reader_settings and type(G_reader_settings.nilOrFalse)=="function"
        and not G_reader_settings:nilOrFalse("page_turns_disable_tap") then
        return false
    end
    if not self.ui then return false end

    -- Prefer KOReader's native page-turn module directly. Some ReaderUI builds
    -- do not propagate a strict boolean from handleEvent even though GotoViewRel
    -- is handled, which allowed the thought link to open after the page turn path.
    local native=self.ui.rolling or self.ui.paging
    local turned=false
    if native and type(native.onGotoViewRel)=="function" then
        local ok,result=pcall(native.onGotoViewRel,native,diff)
        if ok and result~=false then
            turned=true
        elseif not ok then
            logger.warn("[MiuRead][ThoughtPopup] edge page turn failed",tostring(result))
        end
    elseif type(self.ui.handleEvent)=="function" then
        local ok,handled=pcall(self.ui.handleEvent,self.ui,Event:new("GotoViewRel",diff))
        -- Event dispatch is only a compatibility fallback. Treat any non-false
        -- successful result as consumed so the underlying comment cannot reopen.
        turned=ok and handled~=false
    end
    if not turned then return false end
    self:_mark_reader_busy(2)
    logger.info("[MiuRead][ThoughtPopup] edge annotation tap converted to page turn",
        "percent=",tostring(percent),"direction=",diff<0 and "backward" or "forward")
    return true
end

function Plugin:_on_thought_tap(ges)
    -- beta.17: visible MiuRead content owns the tap before Gesture Manager.
    -- This prevents a comment near a configured corner from becoming an
    -- unintended bookmark, while still forwarding genuinely unused taps to
    -- KOReader after the transition guard expires.
    if self:_reader_gesture_guard_active() then
        logger.info("[MiuRead][ReaderGesture] stale reader tap suppressed")
        return true
    end
    local link
    if self.ui and self.ui.link and self.ui.link.getLinkFromGes then
        local ok,value=pcall(self.ui.link.getLinkFromGes,self.ui.link,ges)
        if ok then link=value end
    end
    if link then
        local href=extract_thought_href(link,{},0)
        if href then
            if self:_thought_edge_page_turn(ges) then return true end
            return self:_show_thought_href(href)
        end
    end
    if self:_reader_top_menu_tap(ges) then
        logger.info("[MiuRead][ReaderToolbar] opened by top tap through thought layer")
        return self:show_reader_quick_panel()
    end
    if GestureBridge.dispatch(ges) then return true end
    return false
end
function Plugin:_setup_thought_tap()
    if self._thought_tap_setup or not self.ui or not self.ui.registerTouchZones then return end
    local ok,Device=pcall(require,"device"); if ok and Device.isTouchDevice and not Device:isTouchDevice() then return end
    self.ui:registerTouchZones({{id="miuread_thought_popup",ges="tap",screen_zone={ratio_x=0,ratio_y=0,ratio_w=1,ratio_h=1},overrides={"tap_link"},handler=function(ges) return self:_on_thought_tap(ges) end}})
    self._thought_tap_setup=true
end

function Plugin:_record_recent_read(path,book,record)
    path=normalized_reader_file(path) or tostring(path or "")
    local book_id=tostring((book and (book.book_id or book.bookId))
        or (record and (record.book_id or record.bookId)) or "")
    if path=="" and book_id=="" then return false end
    local stamp=os.time()
    if self.store.record_recent_read then
        self.store:record_recent_read(book_id,path,stamp)
    elseif book_id~="" then
        self.store:mark_last_read(book_id,path,nil,false,stamp)
    end
    self:_home_share_recent_read(book_id,path,stamp)
    self._home_recent_read_dirty=true
    HOME_SESSION.recent_read_dirty=true

    -- Keep one authoritative in-memory snapshot for the current session. Home
    -- Hero and Home lockscreen both consume this same object, so neither waits
    -- for a shelf rescan or a manual refresh after the Reader closes.
    local snapshot=self:_home_build_recent_snapshot(book_id,path,stamp,book,record)
    HOME_SESSION.recent_read_snapshot=snapshot

    local owner=home_owner()
    if owner and owner~=self then
        -- Keep the parked Home instance's store and dirty marker current too.
        -- Store writes remain deferred; no network/shelf scan is introduced on
        -- ReaderReady or page turns.
        if owner.store and owner.store.record_recent_read then
            owner.store:record_recent_read(book_id,path,stamp)
        elseif owner.store and book_id~="" then
            owner.store:mark_last_read(book_id,path,nil,false,stamp)
        end
        owner._home_recent_read_dirty=true
    end

    -- Lockscreen target changes immediately when Reader identifies the book.
    -- This is local-only and avoids the old window where Home still pointed to
    -- the previous Hero until its delayed refresh ran.
    local lock_owner=owner or self
    if lock_owner and type(lock_owner._home_update_lockscreen_session)=="function" then
        local ok_lock,lock_err=pcall(lock_owner._home_update_lockscreen_session,lock_owner,snapshot)
        if not ok_lock then
            logger.warn("[MiuRead][Recent] lockscreen target update failed",tostring(lock_err))
        end
    end

    logger.info("[MiuRead][Recent] committed",
        "book=",book_id~="" and book_id or "local","file=",tostring(path),
        "read_at=",tostring(stamp),"shared=true","lockscreen=updated")
    return true
end

function Plugin:on_sync_record_ready(current)
    if not self:_reader_session_is_weread() then
        logger.info("[MiuRead][ReaderSession] stale sync record ignored",
            "kind=",self:_reader_session_kind())
        return
    end
    self:_teardown_thought_tap()
    if current and current.book then
        local book_id,path=tostring(current.book.book_id),current.path
        local record=current.record or {}
        local variant=tostring(current.variant or record.variant or "")
        if record.annotation_requested==true or variant:find("notes",1,true) then
            self:_setup_thought_tap()
        end
        -- ReaderReady already records the file immediately in LuaSettings
        -- memory. Once Sync resolves the canonical book id, backfill that id
        -- without a synchronous disk flush or another delayed timer.
        self:_record_recent_read(path,current.book,current.record)
    end
    -- A late identity result is allowed to finish while the device is locking,
    -- but it must not restart cloud checks or the 60 s worker after the final
    -- reading position has already been frozen. This was the beta.3 suspend race.
    local reading_end_barrier=self._reading_end_barrier_active==true
        or self._reading_end_sync_active==true
        or (self.sync and self.sync.reading_end_finalized==true)
        or self._miuread_suspended==true or HOME_SESSION.suspended==true
    if reading_end_barrier then
        logger.info("[MiuRead][ReadingEnd] late reader record accepted without restart",
            "book=",tostring(current and current.book and current.book.book_id or "-"))
        return
    end
    if current and current.book then self:_schedule_current_book_repair_check(current,false) end
    local sync_prefs=self.store:preferences().sync or {}
    local need_cloud_check=sync_prefs.pull_on_open~=false
    if sync_prefs.time_enabled==true then
        self.sync:start("reader_ready_time_only")
    end
    if need_cloud_check then
        local chapter_switch=self._reader_chapter_switch_preserved==true
        local internal_rebuild=self._reader_session_preserved==true and not chapter_switch
        if chapter_switch then
            -- Moving to the next cached chapter is still the same reading
            -- session. Never pull cloud progress here and risk jumping back to
            -- the chapter we just left.
            self.sync:end_progress_sync("同一本书章节切换沿用当前阅读会话")
        elseif internal_rebuild and self.sync:is_current_verified() then
            self.sync:end_progress_sync("内部重建沿用本次阅读已确认的位置")
        else
            -- A genuine reopen still reads the current WeRead position, but the
            -- request is allowed to discover offline/transport failure inside
            -- its async worker. Never run isOnline() on the ReaderReady UI path.
            UIManager:scheduleIn(.08,function()
                if self.ui and self.ui.document and not reader_close_active() then
                    self:ensure_read_report_progress("reader_ready",true)
                end
            end)
        end
    end
end
function Plugin:on_sync_record_missing()
    logger.dbg("[MiuRead][Sync] external EPUB ignored")
end
function Plugin:_reader_rebuild_cancel(reason,clear_shared)
    local owner=READER_REBUILD.owner
    if owner and owner._reader_rebuild_task then
        pcall(UIManager.unschedule,UIManager,owner._reader_rebuild_task)
        owner._reader_rebuild_task=nil
    end
    if self._reader_rebuild_task then
        UIManager:unschedule(self._reader_rebuild_task)
        self._reader_rebuild_task=nil
    end
    READER_REBUILD.generation=(tonumber(READER_REBUILD.generation) or 0)+1
    if clear_shared~=false then
        READER_REBUILD.state="idle"
        READER_REBUILD.session_generation=0
        READER_REBUILD.reader_file=nil
        READER_REBUILD.started_at=0
        READER_REBUILD.started_clock=0
        READER_REBUILD.max_wait=0
        READER_REBUILD.reason=nil
        READER_REBUILD.owner=nil
        READER_REBUILD.pending_width=nil
        READER_REBUILD.pending_height=nil
        READER_REBUILD.pending_rotation=nil
        READER_REBUILD.internal_hint=false
    end
    if reason then logger.info("[MiuRead][Lifecycle] rebuild watcher cancelled",tostring(reason)) end
    return true
end

function Plugin:_prepare_reader_disappearance(reason)
    self:_uninstall_reader_toolbar_hooks(self.ui,reason or "reader disappeared")
    self:_cancel_chapter_prefetch(reason or "reader disappeared")
    self:_reset_chapter_navigation_context(reason or "reader disappeared")
    if self.ui and self.ui.document and self:_reader_session_is_weread() then
        pcall(function() self:_capture_local_annotation_snapshot("final:"..tostring(reason or "reader_disappeared")) end)
    end
    if self._reader_checkpoint_dirty==true then
        self:_flush_reader_checkpoint(reason or "reader_disappeared",true)
    end
    self:_mark_reader_busy(4)
    self:_close_active_thought_popup(reason or "reader disappeared")
    if ThoughtNativePopup and type(ThoughtNativePopup.cleanup)=="function" then
        pcall(ThoughtNativePopup.cleanup)
    end
    if self._reader_checkpoint_task then
        UIManager:unschedule(self._reader_checkpoint_task)
        self._reader_checkpoint_task=nil
    end
    if self._local_annotation_snapshot_task then
        UIManager:unschedule(self._local_annotation_snapshot_task)
        self._local_annotation_snapshot_task=nil
    end
    if self._reader_sync_ready_task then
        UIManager:unschedule(self._reader_sync_ready_task)
        self._reader_sync_ready_task=nil
    end
    self:_cancel_network_waits()
    self:_cancel_interactive_network(reason or "reader disappeared")
    if self.repair_async and self.repair_async.job and self.repair_async.job.label=="book-migration-check" then
        self.repair_async:cancel(reason or "reader disappeared")
        if self.annotation_async then self.annotation_async:cancel(reason or "reader disappeared") end
    end
    self._repair_prompt_open=false
    self:_teardown_thought_tap()
    self._progress_prompted_book_id=nil
    self._progress_check_running=false
    return true
end

function Plugin:_finalize_reader_instance_close(closing_path,session_generation,options)
    options=type(options)=="table" and options or {}
    local explicit_return=options.explicit_return==true
    local document_switch=options.document_switch==true
    closing_path=normalized_reader_file(closing_path)
        or normalized_reader_file(HOME_SESSION.reader_session_file)
        or normalized_reader_file(HOME_READER_FILE)
    session_generation=tonumber(session_generation) or tonumber(HOME_SESSION.reader_session_generation) or 0

    local continuous_switch=options.continuous_chapter_switch==true
    local detached_sync=self._reading_end_sync_active==true or self._reading_end_home_detached==true
    if not continuous_switch and self.sync and self.sync.reading_end_finalized~=true and self.ui and self.ui.document then
        detached_sync=self:_reading_end_sync(options.reason or "关闭书籍",{show_status=false,timeout=8})==true or detached_sync
    end
    self:_prepare_reader_disappearance(options.reason or "document closed")
    if self.sync and self:_reader_session_is_weread() then
        -- Same-book chapter transitions only save the old chapter locally and
        -- stop its timer. Remote finalization continues at the normal book-close
        -- boundary, so entering a cached chapter never waits on precise sync.
        self.sync:on_close({preserve_async=detached_sync or continuous_switch})
    end

    -- A confirmed switch has a new ReaderUI already alive. Never clear shared
    -- reader markers or start Home/post-reader work from the old plugin instance.
    if document_switch then
        logger.info("[MiuRead][Lifecycle] previous reader finalized after document switch",
            "book=",tostring(closing_path or ""),"session=",tostring(session_generation))
        return true
    end

    HOME_SESSION.reader_session_active=false
    HOME_SESSION.reader_session_kind="none"
    HOME_SESSION.reader_session_book_id=""

    if self._reader_active_path then os.remove(self._reader_active_path) end
    if self._reader_busy_path then
        local busy_path=self._reader_busy_path
        UIManager:scheduleIn(4,function() os.remove(busy_path) end)
    end
    self:_schedule_post_reader_work("document closed",1.4)
    sync_home_session()
    HOME_SESSION.reader_session_active=false

    if explicit_return then
        HOME_SESSION.opening_file=nil
        HOME_SESSION.opening_at=0
    end

    if self:_home_enabled() and HOME_READER_ORIGIN and not HOME_SESSION_SUPPRESSED
        and not HOME_NATIVE_VISIT and not HOME_EXITING then
        self:_set_foreground("reader_transition")
        if explicit_return then
            READER_CLOSE.close_event_received=true
            if READER_CLOSE.state~="native_surface_waiting" then READER_CLOSE.state="document_closed" end
            self._miuread_return_requested=false
            logger.info("[MiuRead][ReaderClose] CloseDocument received",
                "generation=",tostring(READER_CLOSE.generation))
            self:_schedule_reader_return_finish(READER_CLOSE.generation,.10,"explicit close document")
        else
            self:_schedule_reader_close_settle(closing_path,session_generation,"confirmed document close")
        end
    else
        self:_set_foreground("native")
        UIManager:scheduleIn(.12,function()
            if self:_reader_lifecycle_state()~="closed" then return end
            if self:_filemanager_instance() or self:_ensure_filemanager_base(closing_path) then
                if ReaderTransitionGuard.is_shown() then
                    self:_release_reader_transition_guard("native surface restored")
                end
                UIManager:setDirty(nil,"ui")
                self:_finish_page_transition(.8,"native surface restored")
            else
                self:_finish_page_transition(0,"native restore failed")
                self:_show_reader_recovery_surface("KOReader 文件管理器未能恢复")
            end
        end)
    end
    return true
end

function Plugin:_finish_reader_rebuild_candidate(generation,reason)
    if generation~=(tonumber(READER_REBUILD.generation) or 0)
        or not reader_rebuild_active() then return false end
    if HOME_SESSION.suspended==true or self._miuread_suspended==true then
        READER_REBUILD.state="suspended_pending"
        self._reader_rebuild_task=nil
        return false
    end
    local active=self:_active_reader_ui()
    if active and active.document then
        local current=normalized_reader_file(self:_reader_file(active))
        local expected=normalized_reader_file(READER_REBUILD.reader_file)
        if current and expected and current==expected then
            local elapsed=math.floor((monotonic_wall_time()-(tonumber(READER_REBUILD.started_clock) or monotonic_wall_time()))*1000+.5)
            logger.info("[MiuRead][Lifecycle] reader rebuild completed",
                "same_book=true","session=",tostring(READER_REBUILD.session_generation or 0),
                "ms=",tostring(math.max(0,elapsed)))
            self:_reader_rebuild_cancel("same reader returned",true)
            return true
        end
        local old_owner=READER_REBUILD.owner
        local old_path=READER_REBUILD.reader_file
        local old_session=READER_REBUILD.session_generation
        self:_reader_rebuild_cancel("different reader returned",true)
        if old_owner and type(old_owner._finalize_reader_instance_close)=="function" then
            pcall(old_owner._finalize_reader_instance_close,old_owner,old_path,old_session,
                {document_switch=true,reason="reader switched during rebuild candidate"})
        end
        return true
    end

    local elapsed=math.max(0,monotonic_wall_time()-(tonumber(READER_REBUILD.started_clock) or monotonic_wall_time()))
    if elapsed<(tonumber(READER_REBUILD.max_wait) or 2.4) then
        local task
        task=function()
            if self._reader_rebuild_task~=task then return end
            self._reader_rebuild_task=nil
            self:_finish_reader_rebuild_candidate(generation,reason)
        end
        self._reader_rebuild_task=task
        UIManager:scheduleIn(elapsed<1.0 and .18 or .28,task)
        return false
    end

    local old_path=READER_REBUILD.reader_file
    local old_session=READER_REBUILD.session_generation
    self:_reader_rebuild_cancel("candidate confirmed closed",true)
    logger.info("[MiuRead][Lifecycle] rebuild candidate became real close",
        "book=",tostring(old_path or ""),"wait_ms=",tostring(math.floor(elapsed*1000+.5)))
    return self:_finalize_reader_instance_close(old_path,old_session,
        {reason=reason or "rebuild candidate timeout"})
end

function Plugin:_start_reader_rebuild_candidate(closing_path,session_generation,reason,internal_hint)
    self:_reader_rebuild_cancel(nil,true)
    local now=monotonic_wall_time()
    local path=normalized_reader_file(closing_path)
        or normalized_reader_file(HOME_SESSION.reader_session_file)
        or normalized_reader_file(HOME_READER_FILE)
    if path and READER_REBUILD.recent_book==path and now-(tonumber(READER_REBUILD.recent_started_at) or 0)<=10 then
        READER_REBUILD.recent_count=(tonumber(READER_REBUILD.recent_count) or 0)+1
    else
        READER_REBUILD.recent_book=path
        READER_REBUILD.recent_count=1
    end
    READER_REBUILD.recent_started_at=now
    if READER_REBUILD.recent_count>=3 then READER_REBUILD.safe_until=now+15 end

    READER_REBUILD.generation=(tonumber(READER_REBUILD.generation) or 0)+1
    local generation=READER_REBUILD.generation
    READER_REBUILD.state="pending"
    READER_REBUILD.session_generation=tonumber(session_generation) or tonumber(HOME_SESSION.reader_session_generation) or 0
    READER_REBUILD.reader_file=path
    READER_REBUILD.started_at=os.time()
    READER_REBUILD.started_clock=now
    READER_REBUILD.reason=tostring(reason or "CloseDocument without explicit return")
    READER_REBUILD.owner=self
    READER_REBUILD.internal_hint=internal_hint==true

    local recent_dimension=now-(tonumber(HOME_SESSION.last_dimension_event_clock) or 0)<=5
    local recent_resume=now-(tonumber(HOME_SESSION.last_resume_clock) or 0)<=8
    local fuse=(tonumber(READER_REBUILD.safe_until) or 0)>now
    -- ReaderUI marks reloadDocument()/switchDocument() with tearing_down=true.
    -- A same-book internal reload on slower Kindle devices can legitimately
    -- take several seconds, so give that explicit signal a longer bounded
    -- window without delaying ordinary unrequested closes.
    READER_REBUILD.max_wait=READER_REBUILD.internal_hint and 18.0
        or (fuse and 5.5 or ((recent_dimension or recent_resume) and 4.2 or 2.4))
    self:_set_foreground("reader")
    logger.info("[MiuRead][Lifecycle] rebuild candidate",
        "book=",tostring(path or ""),"session=",tostring(READER_REBUILD.session_generation),
        "recent_dimensions=",tostring(recent_dimension),"recent_resume=",tostring(recent_resume),
        "internal_hint=",tostring(READER_REBUILD.internal_hint),"fuse=",tostring(fuse),
        "deadline_ms=",tostring(math.floor(READER_REBUILD.max_wait*1000+.5)))

    local task
    task=function()
        if self._reader_rebuild_task~=task then return end
        self._reader_rebuild_task=nil
        self:_finish_reader_rebuild_candidate(generation,READER_REBUILD.reason)
    end
    self._reader_rebuild_task=task
    UIManager:scheduleIn(.22,task)
    return true
end

function Plugin:_reader_rebuild_ready_state()
    if not reader_rebuild_active() then return false,false end
    local ready_path=normalized_reader_file(self:_current_document_path())
    local expected=normalized_reader_file(READER_REBUILD.reader_file)
    if ready_path and expected and ready_path==expected then
        local preserved_session=tonumber(READER_REBUILD.session_generation) or tonumber(HOME_SESSION.reader_session_generation) or 0
        local elapsed=math.floor((monotonic_wall_time()-(tonumber(READER_REBUILD.started_clock) or monotonic_wall_time()))*1000+.5)
        self:_reader_rebuild_cancel("ReaderReady same book",true)
        HOME_SESSION.reader_session_generation=preserved_session
        HOME_SESSION.reader_session_active=true
        HOME_SESSION.reader_session_file=ready_path
        logger.info("[MiuRead][Lifecycle] reader returned",
            "same_book=true","preserved_session=",tostring(preserved_session),
            "ms=",tostring(math.max(0,elapsed)))
        return true,true
    end
    local old_owner=READER_REBUILD.owner
    local old_path=READER_REBUILD.reader_file
    local old_session=READER_REBUILD.session_generation
    self:_reader_rebuild_cancel("ReaderReady different book",true)
    if old_owner and type(old_owner._finalize_reader_instance_close)=="function" then
        pcall(old_owner._finalize_reader_instance_close,old_owner,old_path,old_session,
            {document_switch=true,reason="different ReaderReady"})
    end
    logger.info("[MiuRead][Lifecycle] reader returned","same_book=false",
        "old=",tostring(old_path or ""),"new=",tostring(ready_path or ""))
    return true,false
end

function Plugin:onReaderReady()
    HOME_SESSION.home_restore_generation=(tonumber(HOME_SESSION.home_restore_generation) or 0)+1
    HOME_SESSION.home_restore_active=false

    local ready_path=normalized_reader_file(self:_current_document_path())
    -- If the same Reader unexpectedly reappears while an explicit Home return
    -- is already in progress, do not cancel that user request. Close the
    -- transiently recreated Reader again and keep the existing close watchdog.
    if reader_close_active() and HOME_SESSION.return_requested==true
        and ready_path and normalized_reader_file(READER_CLOSE.reader_file)==ready_path then
        logger.warn("[MiuRead][Lifecycle] reader reappeared during explicit return",
            "generation=",tostring(READER_CLOSE.generation),"book=",tostring(ready_path))
        READER_CLOSE.state="reader_closing"
        READER_CLOSE.close_event_received=false
        self:_set_foreground("reader_transition")
        self:_ensure_reader_transition_guard("reader reappeared during explicit return")
        self:_schedule_reader_return_finish(READER_CLOSE.generation,.08,"reader reappeared")
        UIManager:nextTick(function()
            if reader_close_active() and HOME_SESSION.return_requested==true then
                self:_request_reader_close(READER_CLOSE.generation,"reappeared during explicit return")
            end
        end)
        return
    end

    local continuous_switch=HOME_SESSION.chapter_switch_active==true
        and ready_path and normalized_reader_file(HOME_SESSION.chapter_switch_target)==ready_path
        and tostring(HOME_SESSION.chapter_switch_book_id or "")~= ""
        and tostring(HOME_SESSION.chapter_switch_book_id or "")==tostring(HOME_SESSION.reader_session_book_id or "")
    local had_candidate,preserve_session=self:_reader_rebuild_ready_state()
    if continuous_switch then preserve_session=true end
    self:_reader_session_classify_ready(ready_path,preserve_session)
    self:_cancel_reader_close_settle("reader ready")
    if READER_CLOSE.state~="idle" then
        self:_clear_reader_return(READER_CLOSE.generation,"reader ready cancelled stale return")
        self:_finish_page_transition(1.0,"reader ready")
    elseif not preserve_session then
        HOME_SESSION.return_requested=false
        HOME_SESSION.return_session_generation=0
        HOME_SESSION.return_request_file=nil
    end
    if not preserve_session then
        HOME_SESSION.reader_session_generation=(tonumber(HOME_SESSION.reader_session_generation) or 0)+1
    end
    HOME_SESSION.reader_session_active=true
    HOME_SESSION.reader_session_file=ready_path
    self._reader_session_generation=HOME_SESSION.reader_session_generation
    -- A preserved Reader session is either an internal KOReader rebuild or a
    -- same-book chapter handoff. Both keep the already verified cloud session;
    -- every genuine book reopen still re-reads WeRead.
    self._reader_session_preserved=preserve_session==true
    self._reader_chapter_switch_preserved=continuous_switch==true
    if not preserve_session then self._reading_end_home_detached=false end
    local ready_session=self._reader_session_generation
    self._home_reader_transition=false
    self:_close_reader_recovery_surface()
    self:_close_home_for_reader("reader ready")
    self:_ensure_reader_transition_guard("reader ready")
    if self._reader_active_path then U.atomic_write(self._reader_active_path,"1",true) end
    -- Give EPUB opening and the first visible page priority over background
    -- work, but do not keep cloud/state workers blocked for a fixed eight
    -- seconds. Three seconds is enough to protect the first interactions; the
    -- idle gate below keeps extending the delay while the user is active.
    self:_mark_reader_busy(3)
    logger.info("[MiuRead][Sync] reader ready","session=",tostring(self._reader_session_generation or 0),
        "rebuild=",tostring(had_candidate==true),"preserved=",tostring(preserve_session==true))
    self:_arm_reader_gesture_guard(preserve_session==true and .20
        or tonumber(Config.READER_OPEN_GESTURE_GUARD_SECONDS) or .75,
        continuous_switch and "chapter switch" or (preserve_session==true and "reader rebuild" or "reader open"))
    -- ReaderUI already paints its first page. Avoid a second forced full-screen
    -- refresh, which was the visible extra flash after opening a book.
    self:_finish_page_transition(1.2,"reader first page")
    UIManager:scheduleIn(.05,function()
        if not (self.ui and self.ui.document)
            or tonumber(HOME_SESSION.reader_session_generation or 0)~=ready_session
            or reader_close_active() then return end
        self:_install_book_excerpt_highlight_action()
        local highlight=self.ui and self.ui.highlight or nil
        if highlight then
            local ok,installed,reason=pcall(HighlightMenu.install,highlight)
            if not ok or installed~=true then
                logger.warn("[MiuRead][HighlightMenu] install failed",tostring(ok and reason or installed))
            end
        end
        self:_sync_reader_toolbar_hooks("reader ready")
        if continuous_switch then
            -- Keep the shared switch target around briefly so the old ReaderUI
            -- can still classify a late CloseDocument as the same-book handoff.
            local switch_target=ready_path
            UIManager:scheduleIn(.45,function()
                if normalized_reader_file(HOME_SESSION.chapter_switch_target)~=switch_target then return end
                HOME_SESSION.opening_file=nil
                HOME_SESSION.opening_at=0
                HOME_SESSION.opening_kind=""
                HOME_SESSION.opening_book_id=""
                self:_clear_chapter_switch_state("target reader settled")
            end)
        else
            HOME_SESSION.opening_file=nil
            HOME_SESSION.opening_at=0
            HOME_SESSION.opening_kind=""
            HOME_SESSION.opening_book_id=""
        end
        local path=self:_current_document_path()
        local book,record,variant
        if path then
            if self:_reader_session_is_weread() then
                book,record,variant=self.store:file_record_fast(path,false)
                if not book then book,record,variant=self.store:identify_file(path,false) end
                if record then self:_consume_opened_prefetch(path,book,record,variant) end
            end
            self:_record_recent_read(path,book,record)
        end
        if record and (record.annotation_requested==true or tostring(variant or record.variant or ""):find("notes",1,true)) then
            self:_setup_thought_tap()
            logger.info("[MiuRead][ThoughtPopup] local tap ready before cloud sync")
        end
        local pending=HOME_SESSION.pending_annotation_jump
        if type(pending)=="table" then
            local age=os.time()-(tonumber(pending.requested_at) or 0)
            if age<0 or age>45 then
                HOME_SESSION.pending_annotation_jump=nil
            else
                local current_id=book and tostring(book.book_id or book.bookId or "") or ""
                local same_book=current_id~="" and current_id==tostring(pending.book_id or "")
                local same_file=normalized_reader_file(path)==normalized_reader_file(pending.source_path)
                if same_book or same_file then
                    HOME_SESSION.pending_annotation_jump=nil
                    UIManager:scheduleIn(.16,function()
                        if not (self.ui and self.ui.document) or reader_close_active() then return end
                        self:_reader_goto_annotation(pending)
                        if pending.manage==true then
                            UIManager:scheduleIn(.14,function()
                                local item=self:_annotation_find_reader_item(pending)
                                if item then
                                    local kind=self:_reader_annotation_type(item)
                                    self:_show_reader_annotation_actions(item,kind,nil,function()
                                        self:_show_reader_records(self:_reader_annotation_type(item) or kind,function() self:show_reader_quick_panel() end)
                                    end)
                                else
                                    self:toast("已跳到批注位置；当前记录暂时无法直接编辑",2)
                                end
                            end)
                        end
                    end)
                end
            end
        end
    end)
    -- Prime only lightweight page/chapter data. No toolbar widget survives a
    -- close or page turn; every visible panel is created fresh and destroyed.
    ReaderToolbar.invalidate()
    self:_reset_reader_toolbar_state_cache()
    self:_reset_chapter_navigation_context("reader ready")
    self._chapter_catalog_confirm_running=false
    if type(self.store.prune_hidden_prefetch)=="function" then
        local removed=self.store:prune_hidden_prefetch(Config.CHAPTER_PREFETCH_TTL)
        if tonumber(removed or 0)>0 then logger.info("[MiuRead][Prefetch] stale cache pruned","count=",tostring(removed)) end
    end
    self:_schedule_reader_toolbar_state_refresh(nil,.35)
    self:_schedule_reader_toolbar_prewarm(ready_session,1.1)
    if self:_reader_session_is_weread() then
        -- Catalog lookup waits for reader idle and is cached once for this
        -- chapter. Prefetch remains delayed until the normal 30 s quiet point.
        self:_schedule_chapter_navigation_context(ready_session,1.8)
        if not preserve_session or continuous_switch then self:_schedule_chapter_prefetch(ready_session) end
    end
    self:_teardown_thought_tap()
    self._progress_prompted_book_id=nil
    self._progress_check_running=false
    self._progress_remote_retries={}
    self._sync_success_notified=false
    self._last_progress_submit_notice=nil
    if self._reader_sync_ready_task then
        UIManager:unschedule(self._reader_sync_ready_task)
        self._reader_sync_ready_task=nil
    end
    local task
    task=function()
        if self._reader_sync_ready_task~=task then return end
        self._reader_sync_ready_task=nil
        if self.ui and self.ui.document
            and tonumber(HOME_SESSION.reader_session_generation or 0)==ready_session
            and not reader_close_active() then self.sync:on_reader_ready() end
    end
    self._reader_sync_ready_task=task
    if self:_reader_session_is_weread() then
        UIManager:scheduleIn(.18,task)
    else
        self._reader_sync_ready_task=nil
        logger.info("[MiuRead][ReaderSession] cloud reader-ready work skipped",
            "kind=",self:_reader_session_kind())
    end
    local device_task
    device_task=function()
        if self._miuread_suspended==true or HOME_SESSION.suspended==true then return end
        if not (self.ui and self.ui.document) or reader_close_active()
            or tonumber(HOME_SESSION.reader_session_generation or 0)~=ready_session then return end
        if not self:_reader_background_idle() then UIManager:scheduleIn(.75,device_task); return end
        HomeData.quick_device_state(true)
    end
    UIManager:scheduleIn(1.8,device_task)
    if had_candidate then
        UIManager:scheduleIn(.18,function()
            if self.ui and self.ui.document
                and tonumber(HOME_SESSION.reader_session_generation or 0)==ready_session
                and not reader_close_active() then self:onSetDimensions() end
        end)
    end
end
function Plugin:onSetDimensions()
    local now=monotonic_wall_time()
    HOME_SESSION.last_dimension_event_clock=now
    self._reader_dimension_last_event_clock=now
    self._reader_dimension_event_count=(tonumber(self._reader_dimension_event_count) or 0)+1
    local sw,sh=Device.screen:getWidth(),Device.screen:getHeight()
    local rotation=Device.screen.getRotationMode and Device.screen:getRotationMode() or nil

    if HOME_SESSION.suspended==true or self._miuread_suspended==true then
        READER_REBUILD.pending_width,READER_REBUILD.pending_height=sw,sh
        READER_REBUILD.pending_rotation=rotation
        return true
    end
    if reader_close_active() then
        HOME_SESSION.pending_dimension_width=sw
        HOME_SESSION.pending_dimension_height=sh
        HOME_SESSION.pending_dimension_rotation=rotation
        logger.info("[MiuRead][Rotation] deferred during reader close",
            "state=",tostring(READER_CLOSE.state),"size=",tostring(sw).."x"..tostring(sh))
        return true
    end
    if reader_rebuild_active() then
        READER_REBUILD.pending_width,READER_REBUILD.pending_height=sw,sh
        READER_REBUILD.pending_rotation=rotation
        logger.info("[MiuRead][Rotation] deferred during reader rebuild",
            "size=",tostring(sw).."x"..tostring(sh))
        return true
    end

    if not (self.ui and self.ui.document) then
        -- HomeWidget owns Home geometry. Avoid a second plugin-level rebuild.
        return true
    end

    self:_set_foreground("reader")
    self._reader_dimension_generation=(tonumber(self._reader_dimension_generation) or 0)+1
    local generation=self._reader_dimension_generation
    local event_count=self._reader_dimension_event_count
    if self._reader_dimension_task then
        UIManager:unschedule(self._reader_dimension_task)
        self._reader_dimension_task=nil
    end
    logger.info("[MiuRead][Rotation] event","generation=",tostring(generation),
        "size=",tostring(sw).."x"..tostring(sh),"rotation=",tostring(rotation))

    local last_w,last_h,last_rotation,stable,attempts=nil,nil,nil,0,0
    local task
    task=function()
        if self._reader_dimension_task~=task or generation~=self._reader_dimension_generation then return end
        if HOME_SESSION.suspended==true or self._miuread_suspended==true then
            self._reader_dimension_task=nil
            return
        end
        if reader_close_active() or reader_rebuild_active() then
            self._reader_dimension_task=nil
            HOME_SESSION.pending_dimension_width=Device.screen:getWidth()
            HOME_SESSION.pending_dimension_height=Device.screen:getHeight()
            HOME_SESSION.pending_dimension_rotation=Device.screen.getRotationMode and Device.screen:getRotationMode() or nil
            return
        end
        attempts=attempts+1
        local cw,ch=Device.screen:getWidth(),Device.screen:getHeight()
        local cr=Device.screen.getRotationMode and Device.screen:getRotationMode() or nil
        if cw==last_w and ch==last_h and cr==last_rotation then
            stable=stable+1
        else
            last_w,last_h,last_rotation,stable=cw,ch,cr,0
        end
        if stable<2 and attempts<8 then
            UIManager:scheduleIn(.12,task)
            return
        end
        self._reader_dimension_task=nil
        if not (self.ui and self.ui.document) then return end
        local changed=cw~=self._reader_dimension_width or ch~=self._reader_dimension_height
            or cr~=self._reader_dimension_rotation
        self._reader_dimension_width,self._reader_dimension_height=cw,ch
        self._reader_dimension_rotation=cr
        if changed then
            self:_close_miuread_transients()
            ReaderToolbar.invalidate()
            self:_reset_reader_toolbar_state_cache()
            self:_schedule_reader_toolbar_state_refresh(nil,.10)
            -- Re-evaluate the mode-specific reader toolbar hooks after a real
            -- geometry commit. Disabled plugin mode remains fully native.
            self:_sync_reader_toolbar_hooks("reader geometry committed")
            local reader=self:_active_reader_ui()
            UIManager:setDirty(reader or nil,"full")
        end
        logger.info("[MiuRead][Rotation] committed",
            "generation=",tostring(generation),"coalesced=",tostring(math.max(1,(tonumber(self._reader_dimension_event_count) or event_count)-event_count+1)),
            "samples=",tostring(attempts),"changed=",tostring(changed),
            "size=",tostring(cw).."x"..tostring(ch),"rotation=",tostring(cr))
    end
    self._reader_dimension_task=task
    UIManager:scheduleIn(.30,task)
    return true
end

function Plugin:onScreenResize() return self:onSetDimensions() end
function Plugin:onRotation() return self:onSetDimensions() end
function Plugin:onPageUpdate(page)
    local weread=self:_reader_session_is_weread()
    -- Only WeRead sessions need to signal the independent 60 s report service.
    -- Ordinary local books keep beta.1's memory-only page-turn path.
    self:_mark_reader_busy(weread and 3 or 2,weread and "fast" or nil)
    local cache=self:_reader_toolbar_cache()
    local current=tonumber(page)
    if current then cache.page=current end
    -- Page turns only update the in-memory position immediately. Chapter/ToC
    -- lookup is delayed until the reader has been idle, keeping the flip path
    -- free of optional work.
    self:_schedule_reader_toolbar_state_refresh(current,.55)
    if weread then
        self.sync:on_page(page)
        self:_schedule_thought_prewarm()
    end
end
function Plugin:_annotation_sync_preferences()
    local p=self.store:preferences()
    p.annotation_sync=type(p.annotation_sync)=="table" and p.annotation_sync or {}
    if p.annotation_sync.enabled==nil then p.annotation_sync.enabled=false end
    if tostring(p.annotation_sync.review_visibility or "")=="" then p.annotation_sync.review_visibility="private" end
    p.annotation_sync.highlight_style=tonumber(p.annotation_sync.highlight_style) or 1
    p.annotation_sync.highlight_color=tonumber(p.annotation_sync.highlight_color) or 0
    return p.annotation_sync,p
end

function Plugin:_reading_end_sync(reason,options,callback)
    options=type(options)=="table" and options or {}
    reason=tostring(reason or "结束阅读")
    if not self:_reader_session_is_weread() then
        logger.info("[MiuRead][ReadingEnd] cloud finalizer skipped",
            "kind=",self:_reader_session_kind(),"reason=",reason)
        return false
    end
    if self.sync and self.sync.reading_end_finalized==true then return false end
    if self._reading_end_sync_active then
        self._reading_end_sync_waiters=self._reading_end_sync_waiters or {}
        if callback then self._reading_end_sync_waiters[#self._reading_end_sync_waiters+1]=callback end
        return true
    end
    local current=self:_current_book_record()
    if not (current and current.book) then return false end
    -- Suspend must be visually immediate: keep only local/barrier setup on the
    -- Suspend callback, then start position/network work after KOReader/powerd
    -- has had a chance to paint the lock screen. The record/ratio snapshots
    -- bind that later work to the book that initiated the suspend.
    local defer_background_start=options.defer_background_start==true
    local deferred_delay=math.max(.08,tonumber(options.defer_background_delay) or .30)
    local record_snapshot=U.copy(current)
    local record_generation_snapshot=self.sync and tonumber(self.sync.record_generation or 0) or 0
    local ratio_snapshot=self.sync and self.sync:local_ratio() or nil

    self._reading_end_barrier_active=true
    self._reading_end_barrier_reason=reason
    local function capture_local_close_state()
        if self._local_annotation_snapshot_task then
            UIManager:unschedule(self._local_annotation_snapshot_task)
            self._local_annotation_snapshot_task=nil
        end
        pcall(function() self:_capture_local_annotation_snapshot("reading_end:"..reason) end)
        if self._reader_checkpoint_dirty==true then
            pcall(function() self:_flush_reader_checkpoint("reading_end:"..reason,true) end)
        end
    end
    -- Local-only state is committed before suspend; this is bounded disk work
    -- and guarantees that deferring network work never weakens crash safety.
    capture_local_close_state()

    local book_id=tostring(current.book.book_id or current.book.bookId or "")
    local need_progress=self:progress_upload_mode()~="manual"
    local close_annotations=self:_annotation_close_upload_enabled()
    local annotation_summary,annotation_summary_err={},nil
    if close_annotations and book_id~="" then
        annotation_summary,annotation_summary_err=LocalAnnotationDatabase.summary_fast(self.store,book_id)
        annotation_summary=annotation_summary or {}
    end
    local annotation_retryable=(tonumber(annotation_summary.pending or 0) or 0)
        +(tonumber(annotation_summary.delete_pending or 0) or 0)
    -- A failed fast summary must not lose a pending mutation. Let the detached
    -- worker perform the authoritative full check later instead of blocking UI.
    local need_annotations=close_annotations and (annotation_retryable>0 or annotation_summary_err~=nil)
    if annotation_summary_err then
        logger.warn("[MiuRead][ReadingEnd] annotation fast summary deferred",
            "book=",book_id,"reason=",tostring(annotation_summary_err))
    end
    local online=self:logged_in() and self:_network_radio_hint()~=false
    local final_elapsed=self.sync and self.sync:_final_elapsed(true) or nil
    local need_time=online and final_elapsed~=nil and tonumber(final_elapsed)>0
    local writer_barrier_seq=nil
    if self.sync then
        writer_barrier_seq=self.sync:stop_fast("reading_end:"..reason,need_time and final_elapsed or 0)
        self.sync.reading_end_finalized=true
    end

    if not online then
        if need_progress and book_id~="" then
            self:_save_progress_state(book_id,"waiting_network","结束阅读时网络不可用；本地阅读位置已保留",nil,nil)
        end
        need_progress=false
        need_annotations=false
    end
    local need_writer_wait=writer_barrier_seq~=nil
    -- beta.12: reading time and final progress are independent close tasks.
    -- Annotation upload is best-effort background work and must never keep the
    -- reader finalizer/standby lease open.
    local function start_annotations_detached()
        if not need_annotations then return false end
        local prefs=U.copy(self:_annotation_sync_preferences())
        local book=U.copy(record_snapshot.book or {})
        local record=U.copy(record_snapshot.record or {})
        local service=self.annotation_sync
        if self.annotation_async and self.annotation_async:busy() then
            logger.info("[MiuRead][ReadingEnd] annotation close sync already busy; local queue retained",
                "book=",book_id)
            return false
        end
        local started=self.annotation_async and self.annotation_async:run("annotation-reading-end",function()
            return service:sync_book(book,record,{preferences=prefs,limit=200,diagnostic_only=false})
        end,function(worker_result)
            local value=worker_result and worker_result.value or nil
            if not (worker_result and worker_result.ok==true and type(value)=="table" and value.ok~=false) then
                logger.warn("[MiuRead][ReadingEnd] annotation close sync incomplete; local queue retained",
                    "book=",book_id)
            end
        end,math.max(15,tonumber(options.timeout) or 12))
        if not started then
            logger.info("[MiuRead][ReadingEnd] annotation close sync deferred; local queue retained",
                "book=",book_id)
        end
        return started==true
    end
    local tasks=(need_writer_wait and 1 or 0)+(need_progress and 1 or 0)
    if tasks<=0 then
        start_annotations_detached()
        self._reading_end_barrier_active=false
        self._reading_end_barrier_reason=nil
        return false
    end

    self._reading_end_sync_active=true
    self._reading_end_sync_waiters={}
    if callback then self._reading_end_sync_waiters[1]=callback end
    local pending=tasks
    local failed=false
    local finished=false
    local timeout_task
    local function complete_one(ok)
        if finished then return end
        if ok==false then failed=true end
        pending=pending-1
        if pending>0 then return end
        finished=true
        self._reading_end_sync_active=false
        self._reading_end_barrier_active=false
        self._reading_end_barrier_reason=nil
        if timeout_task then UIManager:unschedule(timeout_task); timeout_task=nil end
        logger.info("[MiuRead][ReadingEnd] finalizer completed",
            "reason=",reason,"ok=",tostring(not failed),"writer_barrier=",tostring(writer_barrier_seq or "-"))
        local waiters=self._reading_end_sync_waiters or {}
        self._reading_end_sync_waiters=nil
        for _,fn in ipairs(waiters) do pcall(fn,not failed,{failed=failed,local_saved=true}) end
    end
    local timeout=math.max(6,tonumber(options.timeout) or 12)
    timeout_task=function()
        if finished then return end
        finished=true
        failed=true
        self._reading_end_sync_active=false
        self._reading_end_barrier_active=false
        self._reading_end_barrier_reason=nil
        logger.warn("[MiuRead][ReadingEnd] finalizer timeout",
            "reason=",reason,"timeout=",tostring(timeout),"writer_barrier=",tostring(writer_barrier_seq or "-"))
        if self.sync and self.sync.async then pcall(self.sync.async.cancel,self.sync.async,"reading_end_timeout") end
        -- Annotation sync is deliberately detached from the core finalizer in
        -- beta.12. Its local pending queue remains authoritative if suspend
        -- cuts the background worker short.
        local waiters=self._reading_end_sync_waiters or {}
        self._reading_end_sync_waiters=nil
        for _,fn in ipairs(waiters) do pcall(fn,false,{timeout=true,local_saved=true}) end
    end
    UIManager:scheduleIn(timeout,timeout_task)

    if options.show_status~=false then
        local parts={}
        if need_time then parts[#parts+1]="阅读时间" end
        if need_progress then parts[#parts+1]="阅读进度" end
        if need_annotations then parts[#parts+1]="批注（后台）" end
        local detail="正在同步："..table.concat(parts,"、")
        if options.after then detail=detail.."\n完成后将"..tostring(options.after) end
        self:status_toast("正在保存本次阅读",detail,math.min(timeout,5))
    end

    if need_writer_wait then
        self.sync:wait_writer_barrier(writer_barrier_seq,function(ok)
            if finished then return end
            if not ok then
                logger.warn("[MiuRead][ReadingEnd] reading-time writer did not leave before timeout",
                    "book=",book_id,"barrier=",tostring(writer_barrier_seq))
            end
            complete_one(ok)
        end,math.max(4,timeout-1))
    end

    if need_progress then
        local resolve_attempt=0
        local function resolve_final_position()
            resolve_attempt=resolve_attempt+1
            local started,resolve_error=self.sync:resolve_local_progress(function(position,position_error,meta)
                if finished then return end
                if not position then
                    if resolve_attempt<2 and tostring(meta and meta.error_kind or "")=="busy" then
                        UIManager:scheduleIn(.35,resolve_final_position)
                        return
                    end
                    logger.warn("[MiuRead][ReadingEnd] exact position unavailable",
                        "reason=",reason,"book=",book_id,"error=",tostring(position_error or "unknown"))
                    complete_one(false)
                    return
                end
                local snapshot=self:_prepare_progress_snapshot(book_id,position) or position
                self:_save_pending_progress(book_id,snapshot,"final_position_captured")
                logger.info("[MiuRead][ReadingEnd] final position captured",
                    "reason=",reason,"book=",book_id,"seq=",tostring(snapshot.progress_sequence or "-"),
                    "chapter=",tostring(snapshot.chapter_uid or snapshot.chapter_index or "-"),
                    "offset=",tostring(snapshot.canonical_offset or snapshot.chapter_offset or snapshot.offset or "-"),
                    "basis=",tostring(snapshot.offset_basis or snapshot.position_basis or "-"),
                    "progress=",tostring(snapshot.progress or "-"))

                local function submit_final_progress()
                    if finished then return end
                    local upload_started=self:_submit_progress_snapshot(book_id,snapshot,{
                        reason="reading_end_verified",retry_count=1,reading_end=true,
                        detached=defer_background_start,
                        record_snapshot=U.copy(record_snapshot),
                        record_override=U.copy(record_snapshot),
                        record_generation_override=record_generation_snapshot,
                        pending_reason="final_upload_queued",
                        uploading_message="正在上传结束阅读进度",
                        verifying_message="结束阅读进度已提交，正在确认云端位置",
                        retrying_message="云端尚未确认，正在重提交最终精确位置",
                        success_message="结束阅读进度已上传并确认",
                        unconfirmed_message="最终精确位置已保留，云端仍待确认",
                        failed_message="结束阅读进度暂未完成",
                        first_delay=.55,second_delay=.85,retry_delay=.35,
                    },function(ok,remote,err,submitted)
                        if err~="superseded" and not ok then
                            logger.warn("[MiuRead][ReadingEnd] progress remains pending",
                                "book=",book_id,"seq=",tostring(submitted and submitted.progress_sequence or "-"),
                                "reason=",tostring(err or "cloud_not_confirmed"))
                        end
                        complete_one(ok or err=="superseded")
                    end)
                    if not upload_started then complete_one(false) end
                end

                -- beta.12: the final progress request is always rt=0 and uses
                -- its own compatibility worker. Do not wait for the independent
                -- rt!=0 reading-time writer; both may finish in parallel.
                submit_final_progress()
            end,{
                precise=true,prepare_catalog=true,require_cloud_coordinate=true,
                detached=defer_background_start,
                record_snapshot=defer_background_start and U.copy(record_snapshot) or nil,
                record_generation_override=defer_background_start and record_generation_snapshot or nil,
                ratio_snapshot=defer_background_start and ratio_snapshot or nil,
                on_stage=function(stage,detail)
                    if stage=="position_fallback" then
                        logger.info("[MiuRead][ReadingEnd] exact source position fallback rejected",
                            "book=",book_id,"reason=",tostring(detail or "unknown"))
                    end
                end,
            })
            if not started then
                if resolve_attempt<2 then UIManager:scheduleIn(.35,resolve_final_position)
                else
                    logger.warn("[MiuRead][ReadingEnd] cannot start exact position resolver",
                        "book=",book_id,"error=",tostring(resolve_error or "busy"))
                    complete_one(false)
                end
            end
        end
        if defer_background_start then
            UIManager:scheduleIn(deferred_delay,function()
                if finished then return end
                logger.info("[MiuRead][ReadingEnd] deferred suspend progress start",
                    "book=",book_id,"delay=",tostring(deferred_delay))
                resolve_final_position()
            end)
        else
            resolve_final_position()
        end
    end

    if defer_background_start then
        UIManager:scheduleIn(deferred_delay+.06,function()
            if not finished then start_annotations_detached() end
        end)
    else
        start_annotations_detached()
    end
    return true
end

function Plugin:_reading_end_detach_for_home(reason)
    reason=tostring(reason or "返回觅阅主页")
    if not self:_reader_session_is_weread() then return false end
    if not self.sync or self.sync.reading_end_finalized==true then return false end
    if self._reading_end_home_detached==true then return true end

    local current=self.sync:record() or self:_current_book_record()
    if not (current and current.book) then return false end
    local record_snapshot=U.copy(current)
    local book_id=tostring(current.book.book_id or current.book.bookId or "")
    if book_id=="" then return false end
    local record_generation=tonumber(self.sync.record_generation or 0) or 0
    local ratio_snapshot=self.sync:local_ratio()
    local started_at=monotonic_wall_time()

    self._reading_end_home_detached=true
    self._reading_end_barrier_active=true
    self._reading_end_barrier_reason=reason..":foreground_capture"
    if self._local_annotation_snapshot_task then
        UIManager:unschedule(self._local_annotation_snapshot_task)
        self._local_annotation_snapshot_task=nil
    end
    pcall(function() self:_capture_local_annotation_snapshot("reading_end:"..reason) end)
    if self._reader_checkpoint_dirty==true then
        pcall(function() self:_flush_reader_checkpoint("reading_end:"..reason,true) end)
    end

    local need_progress=self:progress_upload_mode()~="manual"
    local close_annotations=self:_annotation_close_upload_enabled()
    local annotation_summary,annotation_summary_err={},nil
    if close_annotations then
        annotation_summary,annotation_summary_err=LocalAnnotationDatabase.summary_fast(self.store,book_id)
        annotation_summary=annotation_summary or {}
    end
    local annotation_retryable=(tonumber(annotation_summary.pending or 0) or 0)
        +(tonumber(annotation_summary.delete_pending or 0) or 0)
    local need_annotations=close_annotations and (annotation_retryable>0 or annotation_summary_err~=nil)
    if annotation_summary_err then
        logger.warn("[MiuRead][ReadingEnd] detached annotation fast summary deferred",
            "book=",book_id,"reason=",tostring(annotation_summary_err))
    end
    -- Home return never probes Internet synchronously. Authentication is local;
    -- the detached HTTP workers decide whether the current link can actually run.
    local authenticated=self:logged_in()
    local final_elapsed=self.sync:_final_elapsed(true)
    local writer_barrier_seq=self.sync:stop_fast("reading_end:"..reason,final_elapsed or 0)
    self.sync.reading_end_finalized=true

    local function refresh_home_sync_state()
        self._home_sync_summary_cache=nil
        self._home_sync_summary_cache_at=nil
        if HomeView.is_shown() and not self:_active_reader_ui() then
            self:_notify_home_data_changed("header")
        end
    end

    if need_progress then
        if not authenticated then
            self:_save_progress_state(book_id,"waiting_network",
                "已保存本机阅读位置；等待登录状态恢复后继续同步",nil,nil)
        else
            local local_percent=ratio_snapshot and math.floor(U.clamp(ratio_snapshot,0,1)*100+.5) or nil
            self:_save_progress_state(book_id,"deferred",
                "本机位置已保存；正在后台定位最终精确坐标",local_percent,nil)
            local resolve_started,resolve_error=self.sync:resolve_local_progress(function(position,position_error,meta)
                if not position then
                    self:_save_progress_state(book_id,"verification_required",
                        "本机阅读位置已保存；最终精确坐标需稍后确认",local_percent,nil)
                    logger.warn("[MiuRead][ReadingEnd] detached final position unavailable",
                        "book=",book_id,"error=",tostring(position_error or (meta and meta.error_kind) or "unknown"))
                    refresh_home_sync_state()
                    return
                end
                local snapshot=self:_prepare_progress_snapshot(book_id,position) or position
                self:_save_pending_progress(book_id,snapshot,"background_final_position_captured")
                self:_save_progress_state(book_id,"uploading",
                    "最终精确位置已保存；正在后台上传",
                    tonumber(snapshot.progress),nil,snapshot.progress_sequence)
                logger.info("[MiuRead][ReadingEnd] detached final position captured",
                    "book=",book_id,"seq=",tostring(snapshot.progress_sequence or "-"),
                    "chapter=",tostring(snapshot.chapter_uid or snapshot.chapter_index or "-"),
                    "offset=",tostring(snapshot.canonical_offset or snapshot.chapter_offset or snapshot.offset or "-"),
                    "basis=",tostring(snapshot.offset_basis or snapshot.position_basis or "-"),
                    "progress=",tostring(snapshot.progress or "-"),
                    "writer_barrier=",tostring(writer_barrier_seq or "-"))

                local submitted=false
                local function submit_final()
                    if submitted then return end
                    submitted=true
                    local started=self:_submit_progress_snapshot(book_id,snapshot,{
                        reason="reading_end_background_verified",retry_count=1,reading_end=true,detached=true,
                        record_snapshot=record_snapshot,record_override=record_snapshot,
                        record_generation_override=record_generation,
                        pending_reason="background_upload_queued",
                        uploading_message="正在后台上传结束阅读进度",
                        verifying_message="请求已提交，正在后台确认",
                        retrying_message="云端尚未确认，正在重提交最终精确位置",
                        success_message="结束阅读进度已上传并确认",
                        unconfirmed_message="最终精确位置已保留，云端仍待确认",
                        failed_message="后台上传暂未完成",
                        busy_message="最终位置已保存；同步任务繁忙，稍后继续处理",
                        first_delay=.65,second_delay=1.0,retry_delay=.4,
                    },function(ok,remote,err,submitted_position)
                        if err~="superseded" and not ok then
                            logger.warn("[MiuRead][ReadingEnd] detached progress remains pending",
                                "book=",book_id,"seq=",tostring(submitted_position and submitted_position.progress_sequence or "-"),
                                "reason=",tostring(err or "cloud_not_confirmed"))
                        end
                        refresh_home_sync_state()
                    end)
                    if not started then
                        self:_save_progress_state(book_id,"deferred",
                            "最终位置已保存；同步任务繁忙，稍后继续处理",
                            tonumber(snapshot.progress),nil,snapshot.progress_sequence)
                    end
                    refresh_home_sync_state()
                end

                -- Home return is fully detached in beta.12: final rt=0
                -- progress starts immediately while the rt!=0 time flush closes
                -- independently in the long-lived service.
                submit_final()
                if writer_barrier_seq and not self.sync:writer_barrier_done(writer_barrier_seq) then
                    self.sync:wait_writer_barrier(writer_barrier_seq,function(ok)
                        logger.info("[MiuRead][ReadingEnd] detached reading-time writer finished",
                            "book=",book_id,"barrier=",tostring(writer_barrier_seq),
                            "ok=",tostring(ok==true))
                    end,20)
                end
            end,{
                precise=true,prepare_catalog=false,require_cloud_coordinate=true,
                detached=true,record_snapshot=record_snapshot,
                record_generation_override=record_generation,
                ratio_snapshot=ratio_snapshot,defer_seconds=1.8,
            })
            if not resolve_started then
                self:_save_progress_state(book_id,"verification_required",
                    "本机阅读位置已保存；最终精确坐标需稍后确认",local_percent,nil)
                logger.warn("[MiuRead][ReadingEnd] detached resolver unavailable",
                    "book=",book_id,"error=",tostring(resolve_error or "busy"))
            end
        end
    end

    if need_annotations and authenticated then
        local prefs=U.copy(self:_annotation_sync_preferences())
        local book=U.copy(current.book or {})
        local record=U.copy(current.record or {})
        local service=self.annotation_sync
        if self.annotation_async and not self.annotation_async:busy() then
            local annotation_started=self.annotation_async:run("annotation-reading-end-background",function()
                return service:sync_book(book,record,{preferences=prefs,limit=200,diagnostic_only=false})
            end,function(worker_result)
                local value=worker_result and worker_result.value or nil
                if not (worker_result and worker_result.ok==true and type(value)=="table" and value.ok~=false) then
                    logger.warn("[MiuRead][ReadingEnd] detached annotation sync incomplete","book=",book_id)
                end
                refresh_home_sync_state()
            end,25)
            if not annotation_started then
                logger.info("[MiuRead][ReadingEnd] annotation background sync deferred","book=",book_id)
            end
        end
    end

    self._reading_end_barrier_active=false
    self._reading_end_barrier_reason=nil
    logger.info("[MiuRead][ReadingEnd] foreground released; cloud work detached",
        "book=",book_id,"progress=",tostring(need_progress),
        "annotations=",tostring(need_annotations),"time=",tostring(final_elapsed~=nil),
        "writer_barrier=",tostring(writer_barrier_seq or "-"),"network=detached",
        "authenticated=",tostring(authenticated),
        "elapsed_ms=",tostring(math.floor((monotonic_wall_time()-started_at)*1000+.5)))
    refresh_home_sync_state()
    return true
end

function Plugin:_reading_end_before_action(reason,after,action)
    if self.sync and self.sync.reading_end_finalized==true then return action() end
    local started=self:_reading_end_sync(reason,{show_status=true,after=after,timeout=10},function(ok)
        if not ok and self:_sync_error_notice_enabled() then
            self:status_toast("阅读记录已保存在本机","云端同步未全部完成，稍后可继续同步",3)
        end
        action()
    end)
    if not started then return action() end
    return true
end

function Plugin:annotation_sync_diagnostic_only()
    return Config.ANNOTATION_COORD_DIAGNOSTIC_ONLY == true
end

function Plugin:annotation_sync_enabled()
    local prefs=self:_annotation_sync_preferences()
    return prefs.enabled==true
end

function Plugin:toggle_annotation_sync()
    local prefs,all=self:_annotation_sync_preferences()
    prefs.enabled=prefs.enabled~=true
    all.annotation_sync=prefs
    self.store:save_preferences(all)
    logger.info("[MiuRead][AnnotationSync] enabled changed",
        "enabled=",tostring(prefs.enabled==true),"mode=manual")
    if prefs.enabled then
        self:toast("本地批注云同步已开启；当前为手动上传",2.5)
    else
        self:toast("本地批注云同步已关闭",2)
    end
    return prefs.enabled
end

function Plugin:annotation_sync_visibility_label()
    local prefs=self:_annotation_sync_preferences()
    local labels={public="公开",friendship="关注可见",private="私密",friends_hidden="屏蔽好友",one_book="共读"}
    return labels[tostring(prefs.review_visibility or "private")] or "私密"
end

function Plugin:set_annotation_sync_visibility(mode)
    local allowed={public=true,friendship=true,private=true,friends_hidden=true,one_book=true}
    mode=allowed[tostring(mode or "")] and tostring(mode) or "private"
    local prefs,all=self:_annotation_sync_preferences()
    prefs.review_visibility=mode
    all.annotation_sync=prefs
    self.store:save_preferences(all)
    self:toast("新想法云端可见范围："..self:annotation_sync_visibility_label(),2)
end

function Plugin:annotation_sync_visibility_menu()
    local labels={{"public","公开"},{"friendship","关注可见"},{"private","私密"},{"friends_hidden","屏蔽好友"},{"one_book","共读"}}
    local rows={}
    for _,item in ipairs(labels) do
        local key,label=item[1],item[2]
        rows[#rows+1]={text=label,checked_func=function()
            local prefs=self:_annotation_sync_preferences(); return tostring(prefs.review_visibility)==key
        end,keep_menu_open=true,callback=function() self:set_annotation_sync_visibility(key) end}
    end
    return rows
end

function Plugin:show_local_annotation_sync_status()
    local current=self:_current_book_record()
    local book_id=current and current.book and tostring(current.book.book_id or current.book.bookId or "") or ""
    if book_id=="" then self:info("请先打开一本觅阅生成的书籍。") return false end
    self:_capture_local_annotation_snapshot("sync_status")
    local summary,err=LocalAnnotationDatabase.summary(self.store,book_id)
    if not summary then self:info("读取本地批注状态失败："..tostring(err or "未知错误")); return false end
    local lines={
        "《"..tostring(current.book.title or "当前书籍").."》",
        "",
        "书签："..tostring(summary.bookmark or 0),
        "划线："..tostring(summary.highlight or 0),
        "想法："..tostring(summary.thought or 0),
        "",
        "已同步："..tostring(summary.synced or 0),
        "可自动重试："..tostring(summary.pending or 0),
        "待删除："..tostring(summary.delete_pending or 0),
        "需要处理："..tostring(summary.action_required or 0),
        "仅保留本地："..tostring(summary.held_local or 0),
        "待处理合计："..tostring((tonumber(summary.pending or 0) or 0)+(tonumber(summary.delete_pending or 0) or 0)+(tonumber(summary.action_required or 0) or 0)),
        "定位失败："..tostring(summary.locate_failed or 0),
        "元数据失败："..tostring(summary.metadata_failed or 0),
        "坐标校验失败："..tostring(summary.coord_failed or 0),
        "结果未知："..tostring(summary.unknown or 0),
        "旧坐标已同步："..tostring(summary.legacy_synced or 0),
    }
    local failures=LocalAnnotationDatabase.failures(self.store,book_id,5)
    if type(failures)=="table" and #failures>0 then
        lines[#lines+1]=""
        lines[#lines+1]="最近失败："
        local kind_label={bookmark="书签",highlight="划线",thought="想法"}
        for _,failure in ipairs(failures) do
            lines[#lines+1]=string.format("- %s：%s",
                kind_label[failure.kind] or tostring(failure.kind or "批注"),
                self:_annotation_sync_friendly_reason(failure))
        end
        lines[#lines+1]=""
        lines[#lines+1]="可在“需要处理的批注同步”中逐条重新定位，或仅保留本地。"
    end
    self:info(table.concat(lines,"\n"))
    return true
end

function Plugin:sync_local_annotations_now(force_diagnostic)
    local diagnostic_only=force_diagnostic==true or self:annotation_sync_diagnostic_only()
    logger.info("[MiuRead][AnnotationSync] manual sync requested",
        diagnostic_only and "mode=coordinate_diagnostic" or "mode=manual", "explicit=true")
    if not self:logged_in() then self:info("请先登录微信读书账号。") return false end
    local current=self:_current_book_record()
    local book_id=current and current.book and tostring(current.book.book_id or current.book.bookId or "") or ""
    if book_id=="" then self:info("请先打开一本觅阅生成的书籍。") return false end
    if self.annotation_async and self.annotation_async:busy() then
        self:toast("本地批注正在同步",1.5)
        return false
    end
    if not self:_capture_local_annotation_snapshot("manual_sync") then
        self:info("保存本地批注状态失败，本次未执行云同步。")
        return false
    end
    if not diagnostic_only then
        local before=LocalAnnotationDatabase.summary(self.store,book_id) or {}
        local retryable=(tonumber(before.pending or 0) or 0)+(tonumber(before.delete_pending or 0) or 0)
        local action_required=tonumber(before.action_required or 0) or 0
        if retryable<=0 and action_required>0 then
            UIManager:show(ConfirmBox:new{
                text="本书没有可以自动重试的新任务。\n\n另有 "..tostring(action_required).." 条批注需要重新确认正文位置。",
                ok_text="查看详情",cancel_text="稍后处理",
                ok_callback=function() self:show_annotation_sync_issues(book_id) end,
            })
            return true
        end
    end
    local prefs=U.copy(self:_annotation_sync_preferences())
    local book=U.copy(current.book or {})
    local record=U.copy(current.record or {})
    local service=self.annotation_sync
    self:toast(diagnostic_only and "正在生成批注坐标诊断…" or "正在同步本地批注…",2)
    local started,err=self.annotation_async:run("annotation-sync",function()
        return service:sync_book(book,record,{preferences=prefs,limit=200,diagnostic_only=diagnostic_only})
    end,function(worker_result)
        if not worker_result or worker_result.ok~=true then
            self:info("本地批注同步失败："..tostring(worker_result and worker_result.error or "后台任务失败"))
            return
        end
        local result=worker_result.value or {}
        if result.ok==false then
            self:info("本地批注同步失败："..tostring(result.error or "未知错误"))
            return
        end
        if result.diagnostic_only==true then
            local lines={
                "批注坐标诊断完成",
                "",
                "云端批注写入：已暂停",
                "导出章节："..tostring(result.diagnostic_exported or 0),
                "检查本地批注："..tostring(result.total or 0),
            }
            if tonumber(result.failed or 0)>0 then
                lines[#lines+1]="定位异常："..tostring(result.failed or 0)
            end
            lines[#lines+1]=""
            lines[#lines+1]="文件目录："
            lines[#lines+1]=tostring(result.diagnostic_root or "")
            lines[#lines+1]=""
            lines[#lines+1]="请把对应章节文件夹、thoughts.sqlite3、local_annotations.sqlite3 和生成的 EPUB 一起给 AI。"
            self:info(table.concat(lines,"\n"))
            return
        end
        local lines={
            tonumber(result.failed or 0)>0 and "本地批注同步完成，但有记录需要处理" or "本地批注同步完成",
            "",
            "已同步："..tostring(result.synced or 0),
            "已删除："..tostring(result.deleted or 0),
            "云端已存在："..tostring(result.reconciled or 0),
            "正文定位需要处理："..tostring(result.locate_failed or 0),
            "章节信息需要处理："..tostring(result.metadata_failed or 0),
            "位置确认需要处理："..tostring(result.coord_failed or 0),
            "结果未知："..tostring(result.unknown or 0),
            "旧坐标已同步："..tostring(result.legacy_synced or 0).."（不会自动重传）",
        }
        if tonumber(result.failed or 0)>0 then lines[#lines+1]="待处理合计："..tostring(result.failed or 0) end
        if type(result.errors)=="table" and #result.errors>0 then
            lines[#lines+1]=""
            lines[#lines+1]="未上传："
            local kind_label={bookmark="书签",highlight="划线",thought="想法"}
            for index,item in ipairs(result.errors) do
                if index>6 then break end
                if type(item)=="table" then
                    lines[#lines+1]=string.format("- %s：%s",
                        kind_label[item.kind] or tostring(item.kind or "批注"),
                        self:_annotation_sync_friendly_reason({kind=item.kind,state=item.state,stage=item.stage,error=item.error}))
                else
                    lines[#lines+1]="- "..U.utf8_truncate(tostring(item),88,"")
                end
            end
            lines[#lines+1]=""
            lines[#lines+1]="以上记录仍保留在本地，没有猜测错误位置。"
        end
        self:info(table.concat(lines,"\n"))
    end,180)
    if not started then self:info("无法启动本地批注同步："..tostring(err or "后台任务不可用")); return false end
    return true
end

function Plugin:_local_annotation_chapter_context(item,current,kind,reason,prepared)
    if type(current)~="table" then return {} end
    local record=type(current.record)=="table" and current.record or {}
    local book=type(current.book)=="table" and current.book or {}
    local manual=reason=="manual_sync"
    local selected,before,after="","",""
    if manual and (kind=="highlight" or kind=="thought") then
        selected,before,after=self:_reader_annotation_selection_context(item,kind)
    end
    local anchor=(kind=="bookmark" and manual) and self:_reader_bookmark_anchor_text(item) or ""

    local standalone_uid=tostring(record.chapter_uid or "")
    if standalone_uid~="" then
        return {
            chapter_uid=standalone_uid,
            chapter_idx=tonumber((record.chapter_map or {})[1] and (record.chapter_map or {})[1].index) or 1,
            selected_text=selected, context_before=before, context_after=after,
            anchor_text=anchor,
        }
    end

    prepared=type(prepared)=="table" and prepared or {}
    local chapter_map=type(prepared.chapter_map)=="table" and prepared.chapter_map
        or (type(record.chapter_map)=="table" and record.chapter_map
        or (type(book.catalog)=="table" and book.catalog or {}))
    if #chapter_map==0 then
        return {selected_text=selected,context_before=before,context_after=after,anchor_text=anchor}
    end

    local toc=prepared.toc or (self.ui and self.ui.toc or nil)
    local toc_index

    -- Prefer the annotation XPointer: for rolling documents it identifies the
    -- real spine position more precisely than an estimated rendered page.
    local xp=self:_reader_annotation_xpointer(item)
    if xp and toc and type(toc.getTocIndexByPage)=="function" then
        local ok,value=pcall(toc.getTocIndexByPage,toc,xp)
        if ok then toc_index=tonumber(value) end
    end

    local page=self:_reader_annotation_page(item)
    if not toc_index and page and toc and type(toc.getTocIndexByPage)=="function" then
        local ok,value=pcall(toc.getTocIndexByPage,toc,page)
        if ok then toc_index=tonumber(value) end
    end
    local toc_rows=type(prepared.toc_rows)=="table" and prepared.toc_rows
        or (toc and type(toc.toc)=="table" and toc.toc or {})
    if page and not toc_index then
        local page_rows=type(prepared.toc_page_rows)=="table" and prepared.toc_page_rows or nil
        if page_rows and #page_rows>0 then
            local lo,hi,best=1,#page_rows,nil
            while lo<=hi do
                local mid=math.floor((lo+hi)/2)
                if page_rows[mid].page<=page then best=page_rows[mid].index; lo=mid+1
                else hi=mid-1 end
            end
            toc_index=best
        else
            local best=-math.huge
            for index,entry in ipairs(toc_rows) do
                local p=tonumber(entry.page or entry.pageno)
                if p and p<=page and p>=best then best=p; toc_index=index end
            end
        end
    end

    local index=math.max(1,math.min(#chapter_map,math.floor(tonumber(toc_index) or 1)))
    local chapter=chapter_map[index] or {}
    local uid=tostring(chapter.uid or chapter.chapterUid or chapter.chapter_uid or "")
    return {
        chapter_uid=uid,
        chapter_idx=tonumber(chapter.index) or index,
        selected_text=selected, context_before=before, context_after=after,
        anchor_text=anchor,
    }
end

function Plugin:_capture_local_annotation_snapshot(reason)
    if not (self.ui and self.ui.document) then return false end
    local total_started=monotonic_wall_time()
    -- During reading Sync already owns the current book record. Avoid a full
    -- Store:reload() before every local snapshot; only fall back when the
    -- reader has not established a sync record yet.
    local current=(self.sync and self.sync:record()) or self:_current_book_record()
    local book_id=current and current.book and tostring(current.book.book_id or current.book.bookId or "") or ""
    if book_id=="" then return false end
    local annotations=(self.ui.annotation and self.ui.annotation.annotations)
        or (self.ui.bookmark and self.ui.bookmark.bookmarks) or {}

    local record=type(current.record)=="table" and current.record or {}
    local book=type(current.book)=="table" and current.book or {}
    local chapter_map=type(record.chapter_map)=="table" and record.chapter_map
        or (type(book.catalog)=="table" and book.catalog or {})
    local prepared={chapter_map=chapter_map,toc_prepare_ms=0}
    if tostring(record.chapter_uid or "")=="" and #chapter_map>0 then
        local toc_started=monotonic_wall_time()
        local toc=self.ui and self.ui.toc or nil
        if toc and type(toc.fillToc)=="function" then pcall(toc.fillToc,toc) end
        local toc_rows=toc and type(toc.toc)=="table" and toc.toc or {}
        local page_rows={}
        for index,entry in ipairs(toc_rows) do
            local page=tonumber(entry.page or entry.pageno)
            if page then page_rows[#page_rows+1]={page=page,index=index} end
        end
        table.sort(page_rows,function(a,b)
            if a.page==b.page then return a.index<b.index end
            return a.page<b.page
        end)
        prepared.toc=toc
        prepared.toc_rows=toc_rows
        prepared.toc_page_rows=page_rows
        prepared.toc_prepare_ms=math.floor((monotonic_wall_time()-toc_started)*1000+.5)
    end

    local snapshot_started=monotonic_wall_time()
    local ok,result=xpcall(function()
        return LocalAnnotationDatabase.snapshot(self.store,book_id,annotations,current.path,function(item,kind)
            return self:_local_annotation_chapter_context(item,current,kind,reason,prepared)
        end)
    end,debug.traceback)
    local snapshot_ms=math.floor((monotonic_wall_time()-snapshot_started)*1000+.5)
    local total_ms=math.floor((monotonic_wall_time()-total_started)*1000+.5)
    if ok and result then
        logger.info("[MiuRead][LocalAnnotations] snapshot saved",
            "book=",book_id,"count=",tostring(result.count or 0),
            "toc_ms=",tostring(prepared.toc_prepare_ms or 0),
            "snapshot_ms=",tostring(snapshot_ms),
            "total_ms=",tostring(total_ms),
            "reason=",tostring(reason or "quiet"))
        return true
    end
    logger.warn("[MiuRead][LocalAnnotations] snapshot failed",
        "book=",book_id,"toc_ms=",tostring(prepared.toc_prepare_ms or 0),
        "snapshot_ms=",tostring(snapshot_ms),"total_ms=",tostring(total_ms),
        "reason=",tostring(reason or "quiet"),tostring(result))
    return false
end

function Plugin:_schedule_local_annotation_snapshot(reason,delay)
    if not (self.ui and self.ui.document) then return false end
    if self._local_annotation_snapshot_task then
        UIManager:unschedule(self._local_annotation_snapshot_task)
        self._local_annotation_snapshot_task=nil
    end
    local task
    task=function()
        if self._local_annotation_snapshot_task~=task then return end
        self._local_annotation_snapshot_task=nil
        self:_capture_local_annotation_snapshot(reason)
    end
    self._local_annotation_snapshot_task=task
    UIManager:scheduleIn(math.max(.5,tonumber(delay) or 2.4),task)
    return true
end

function Plugin:onAnnotationsModified()
    self._reader_checkpoint_dirty=true
    -- KOReader emits this for new, edited and deleted highlights/notes. Save
    -- once after a short quiet period so a later crash cannot discard a whole
    -- reading session, without writing on every pen movement.
    self:_schedule_reader_checkpoint("annotations_modified",2.0)
    -- Mirror KOReader's local records after the same quiet period. This phase is
    -- local-only: no range calculation and no network request runs in the pen/
    -- gesture callback.
    self:_schedule_local_annotation_snapshot("annotations_modified",2.4)
end
function Plugin:_finish_suspend_reader_finalizer(ok)
    local still_suspended=HOME_SESSION.suspended==true and self._miuread_suspended==true

    if not still_suspended then
        self._reading_end_standby_held=false
        SuspendWorkLease.release("reader_finalizer")
        pcall(PseudoLockscreen.set_task_active,"reader_finalizer",false)
        pcall(PseudoLockscreen.background_task_done,"reader_finalizer_user_visible")
        logger.info("[MiuRead][Power] reader finalizer ended after user wake",
            "ok=",tostring(ok==true))
        return true
    end

    local download_continue,download_reason=false,"no_download"
    if self:_passive_prefetch_active() then
        download_reason="passive_prefetch"
    elseif self.download_task and type(self.download_task.can_continue_locked)=="function" then
        local checked,value,reason=pcall(self.download_task.can_continue_locked,self.download_task)
        if checked then
            download_continue=value==true
            download_reason=tostring(reason or "unknown")
        else
            download_reason="check_failed"
        end
    end
    local hold_active=PseudoLockscreen.active()==true
    local hold_platform=PseudoLockscreen.device_platform()
    local hold_state=hold_platform=="kindle" and "SCREEN_SAVER_HOLD" or "PSEUDO_LOCKED"
    local target=hold_active and hold_state
        or (download_continue and "DOWNLOAD_LOCKED" or "REAL_SUSPEND")
    local power=PowerState.transition(target,"reading_end_complete",{
        download_active=self.download_task and self.download_task:busy() or false,
        download_continue=download_continue,sync_continue=false,
    })
    self._power_suspend_generation=power.generation
    -- Download and reader_finalizer leases coexist in beta.12. If a download
    -- is still active it simply keeps its own lease; no pause/resume handoff is
    -- needed when final progress/time work ends.
    if self.download_task then
        local download_target=self:_passive_prefetch_active() and "REAL_SUSPEND" or target
        self.download_task:on_suspend(download_target,power.generation)
    end
    self._reading_end_standby_held=false
    SuspendWorkLease.release("reader_finalizer")
    pcall(PseudoLockscreen.set_task_active,"reader_finalizer",false)
    pcall(PseudoLockscreen.background_task_done,"reader_finalizer")
    logger.info("[MiuRead][Power] reader finalizer completed",
        "ok=",tostring(ok==true),"to=",tostring(target),
        "generation=",tostring(power.generation),
        "download_continue=",tostring(download_continue),
        "download_reason=",download_reason)
    return true
end

function Plugin:_suspend_lease_names(snapshot)
    local names={}
    for reason,enabled in pairs(type(snapshot)=="table" and snapshot.reasons or {}) do
        if enabled==true then names[#names+1]=tostring(reason) end
    end
    table.sort(names)
    return #names>0 and table.concat(names,",") or "none"
end

function Plugin:_power_diagnostic(kind,power_state,download_continue,download_reason)
    local device=HomeData.quick_power_state(true) or {}
    local leases=SuspendWorkLease.snapshot()
    local pseudo=PseudoLockscreen.snapshot()
    local memory=RuntimePressure.memory_snapshot(false)
    local stage=self.download_task and type(self.download_task.stage)=="function"
        and self.download_task:stage() or "none"
    logger.info("[MiuRead]["..tostring(kind or "PowerDiagnostic").."]",
        "battery=",tostring(device.battery or "unknown"),
        "charging=",tostring(device.charging==true),
        "power=",tostring(power_state or PowerState.state()),
        "download=",tostring(download_continue==true),
        "download_reason=",tostring(download_reason or "unknown"),
        "stage=",tostring(stage or "none"),
        "pseudo_lock=",tostring(pseudo.active==true),
        "leases=",self:_suspend_lease_names(leases),
        "memory_kb=",tostring(memory and memory.available_kb or "unknown"),
        "return_target=",tostring(HOME_SESSION.return_target or "none"))
    return true
end

function Plugin:_reconcile_power_leases(context)
    local power=PowerState.state()
    if not PseudoLockscreen.active() and SuspendWorkLease.has("pseudo_lockscreen") then
        logger.warn("[MiuRead][SuspendLease] orphan pseudo lease released",
            "context=",tostring(context or "unknown"),"power=",tostring(power))
        SuspendWorkLease.release("pseudo_lockscreen")
    end
    if not PseudoLockscreen.active() and SuspendWorkLease.has("download")
        and power~="PSEUDO_LOCKED" and power~="SCREEN_SAVER_HOLD"
        and power~="DOWNLOAD_LOCKED" and power~="SUSPEND_PENDING" then
        logger.warn("[MiuRead][SuspendLease] orphan download lease released",
            "context=",tostring(context or "unknown"),"power=",tostring(power))
        SuspendWorkLease.release("download")
    end
    return true
end

function Plugin:_refresh_home_power_header(reason)
    HomeData.quick_power_state(true)
    if HomeView.is_shown() and not self:_active_reader_ui()
        and HOME_SESSION.suspended~=true and self._miuread_suspended~=true then
        HomeView.update_header{battery_text=self:_home_battery_text()}
        logger.info("[MiuRead][HomeBattery] refreshed",
            "reason=",tostring(reason or "power_event"),
            "value=",tostring(self:_home_battery_text()))
        return true
    end
    return false
end


function Plugin:_schedule_frontlight_ui_refresh(delay)
    if self._frontlight_ui_refresh_task then
        UIManager:unschedule(self._frontlight_ui_refresh_task)
        self._frontlight_ui_refresh_task=nil
    end
    local task
    task=function()
        if self._frontlight_ui_refresh_task~=task then return end
        self._frontlight_ui_refresh_task=nil
        if HOME_SESSION.suspended==true or self._miuread_suspended==true then return end
        if type(HomeQuickPanel.refreshFrontlight)=="function" then pcall(HomeQuickPanel.refreshFrontlight) end
        if type(ReaderToolbar.refreshFrontlight)=="function" then pcall(ReaderToolbar.refreshFrontlight) end
    end
    self._frontlight_ui_refresh_task=task
    UIManager:scheduleIn(math.max(.02,tonumber(delay) or .08),task)
end

function Plugin:onFrontlightStateChanged()
    -- KOReader is the source of truth. Debounce native state broadcasts so a
    -- dragged slider cannot turn into a repaint storm.
    self:_schedule_frontlight_ui_refresh(.08)
end

function Plugin:onCharging()
    return self:_refresh_home_power_header("charging")
end

function Plugin:onNotCharging()
    return self:_refresh_home_power_header("not_charging")
end

function Plugin:onSuspend()
    -- 书摘局域网传输只属于前台交互。任何 Suspend 边沿都先关闭它，
    -- 不申请下载/同步的后台保活，也不会在 Resume 后自动恢复。
    BookExcerptDialog.close("suspend")
    -- A backend may receive duplicate Suspend edges while its visual lock is
    -- already active. Kindle beta.4 never synthesizes Wake; deep-suspend hold
    -- is handled only at powerd ReadyToSuspend. Kobo keeps its legacy path.
    local pseudo_suspend=PseudoLockscreen.on_suspend_while_active()
    if pseudo_suspend=="unlock" then
        logger.info("[MiuRead][Power] pseudo lock unlock suspend intercepted")
        return
    elseif pseudo_suspend=="hold" then
        logger.info("[MiuRead][Power] internal pseudo-lock suspend held",
            "generation=",tostring(PowerState.generation()))
        return
    elseif pseudo_suspend=="commit" then
        -- The system is now entering the real sleep that was postponed while
        -- downloading. Re-run the normal suspend bookkeeping from a clean edge.
        self._miuread_suspended=false
        HOME_SESSION.suspended=false
        logger.info("[MiuRead][Power] pseudo lock committed to real suspend")
    end
    local sleep_origin=PseudoLockscreen.consume_user_sleep_origin()
    if sleep_origin then
        logger.info("[MiuRead][ReadingLifecycle] USER_SLEEP",
            "origin=",tostring(sleep_origin),"sync=finalize_once")
    end
    if HOME_SESSION.suspended==true and self._miuread_suspended==true then
        logger.info("[MiuRead][Power] duplicate suspend ignored",
            "state=",PowerState.state(),"generation=",tostring(PowerState.generation()))
        return
    end
    self:_reconcile_power_leases("pre_suspend")
    local download_continue,download_reason=false,"no_download"
    if self:_passive_prefetch_active() then
        download_reason="passive_prefetch"
        logger.info("[MiuRead][Prefetch] paused reason=suspend")
    elseif self.download_task and type(self.download_task.can_continue_locked)=="function" then
        local ok,value,reason=pcall(self.download_task.can_continue_locked,self.download_task)
        if ok then download_continue=value==true; download_reason=tostring(reason or "unknown")
        else download_reason="check_failed" end
    end
    local sync_continue=false
    local suspend_background_supported=PseudoLockscreen.background_supported()==true
    local sync_candidate=suspend_background_supported
        and self.ui and self.ui.document and self:_reader_session_is_weread()
        and self.sync and self.sync.reading_end_finalized~=true
    local pseudo_active=false
    local power_platform=PseudoLockscreen.device_platform()
    if power_platform=="kindle" then
        pcall(PseudoLockscreen.set_download_active,download_continue)
        if sync_candidate then pcall(PseudoLockscreen.set_task_active,"reader_finalizer",true) end
    end
    local wants_background=download_continue or (power_platform=="kindle" and sync_candidate)
    if wants_background then
        local ok,entered,reason=pcall(PseudoLockscreen.begin,download_continue and "download_or_sync" or "reader_finalizer")
        pseudo_active=ok and entered==true
        logger.info("[MiuRead][Power] background hold request",
            "platform=",tostring(power_platform),
            "active=",tostring(pseudo_active),"reason=",tostring(ok and reason or entered or "error"))
        if not pseudo_active then
            if download_continue then
                download_continue=false
                download_reason="background_hold_failed:"..tostring(ok and reason or entered or "error")
                if power_platform=="kindle" then pcall(PseudoLockscreen.set_download_active,false) end
            end
            if power_platform=="kindle" and sync_candidate then
                sync_candidate=false
                pcall(PseudoLockscreen.set_task_active,"reader_finalizer",false)
            end
        end
    end
    -- Download-only suspend can arm the shared lease and platform network
    -- intent immediately. This still runs inside KOReader's real Suspend
    -- callback, so ordinary Home remains free to enter the lock screen.
    if download_continue and self.download_task
        and type(self.download_task.prepare_suspend_lock)=="function" then
        local ok,prepared,reason=pcall(self.download_task.prepare_suspend_lock,self.download_task)
        logger.info("[MiuRead][Power] early download suspend lock",
            "prepared=",tostring(ok and prepared==true),
            "reason=",tostring(ok and reason or prepared or "error"))
    end
    if sync_candidate then
        -- beta.12: final progress/time synchronization no longer owns the
        -- download lane. Both leases are held at the same time and both network
        -- jobs continue behind the already-painted lock screen.
        local lease_ok=SuspendWorkLease.acquire("reader_finalizer")
        self._reading_end_standby_held=lease_ok==true
        sync_continue=self:_reading_end_sync("休眠",{
            show_status=false,timeout=18,
            -- Acquire the reader_finalizer lease and arm the reading-time
            -- barrier now, but postpone the costly exact-position/network
            -- phase until after the visual lock transition returns.
            defer_background_start=true,defer_background_delay=.30,
        },function(ok)
            self:_finish_suspend_reader_finalizer(ok)
            if ok then
                logger.info("[MiuRead][ReadingEnd] suspend sync completed")
            else
                logger.warn("[MiuRead][ReadingEnd] suspend sync incomplete; local state retained")
            end
        end)==true
        if not sync_continue then
            self._reading_end_standby_held=false
            SuspendWorkLease.release("reader_finalizer")
            pcall(PseudoLockscreen.set_task_active,"reader_finalizer",false)
            pcall(PseudoLockscreen.background_task_done,"reader_finalizer_not_started")
        end
    end
    -- Kindle keeps Amazon powerd in its native screenSaver state and only
    -- blocks the later ReadyToSuspend edge. Kobo retains its legacy pseudo lock.
    -- The finalizer alone is also power-critical on Kindle, so it shares the
    -- same SCREEN_SAVER_HOLD session as a download.
    local backend_active=(pseudo_active or PseudoLockscreen.active())==true
    local backend_hold_state=power_platform=="kindle" and "SCREEN_SAVER_HOLD" or "PSEUDO_LOCKED"
    local power_target=download_continue
        and (backend_active and backend_hold_state or "DOWNLOAD_LOCKED")
        or (sync_continue
            and ((power_platform=="kindle" and backend_active) and "SCREEN_SAVER_HOLD" or "BACKGROUND_LOCKED")
            or "REAL_SUSPEND")
    local power=PowerState.transition(power_target,"onSuspend",{
        download_active=self.download_task and self.download_task:busy() or false,
        download_continue=download_continue,
        sync_continue=sync_continue,
    })
    self._power_suspend_generation=power.generation
    logger.info("[MiuRead][Power] suspend transition",
        "from=",tostring(power.previous),"to=",tostring(power.state),
        "generation=",tostring(power.generation),
        "download_continue=",tostring(download_continue),
        "download_reason=",download_reason,
        "reader_finalizer=",tostring(sync_continue),
        "sleep_origin=",tostring(sleep_origin or "device_or_koreader"))
    self:_power_diagnostic("SleepDiagnostic",power_target,download_continue,download_reason)

    self._miuread_suspended=true
    HOME_SESSION.suspended=true
    HOME_SESSION.foreground_before_suspend=HOME_SESSION.foreground
    HOME_SESSION.navigation_before_suspend=self:_navigation_state()
    self:_set_foreground("suspended")
    StatusToast.set_blocked(true)
    StatusToast.close()
    self:_cancel_thought_prewarm("suspend")
    self:_cancel_interactive_network("suspend")
    if self._local_annotation_snapshot_task then
        UIManager:unschedule(self._local_annotation_snapshot_task)
        self._local_annotation_snapshot_task=nil
    end
    self:_close_miuread_transients()
    self:_cancel_reader_close_settle("suspend")
    if self._home_resume_surface_task then
        UIManager:unschedule(self._home_resume_surface_task)
        self._home_resume_surface_task=nil
    end
    if self._reader_resume_surface_task then
        UIManager:unschedule(self._reader_resume_surface_task)
        self._reader_resume_surface_task=nil
    end
    local suspend_sync=self.sync
    if self.ui and self.ui.document and not self:_reader_session_is_weread() then suspend_sync=nil end
    if reader_rebuild_active() then
        local owner=READER_REBUILD.owner
        if owner and owner._reader_rebuild_task then
            pcall(UIManager.unschedule,UIManager,owner._reader_rebuild_task)
            owner._reader_rebuild_task=nil
        end
        if owner and owner~=self and owner.sync and type(owner.sync.on_suspend)=="function" then
            suspend_sync=owner.sync
        end
        READER_REBUILD.state="suspended_pending"
    end
    if HomeView.suspend then HomeView.suspend() end
    if READER_CLOSE.state=="idle" and HOME_SESSION.return_target~="home" then
        HOME_SESSION.return_requested=false
        HOME_SESSION.return_session_generation=0
        HOME_SESSION.return_request_file=nil
    elseif HOME_SESSION.return_target=="home" then
        logger.info("[MiuRead][ReaderClose] home target preserved across suspend",
            "session=",tostring(HOME_SESSION.return_session_generation or 0),
            "file=",tostring(HOME_SESSION.return_request_file or ""))
    end
    if self._reader_dimension_task then
        UIManager:unschedule(self._reader_dimension_task)
        self._reader_dimension_task=nil
    end
    if self._reader_checkpoint_dirty==true then
        self:_flush_reader_checkpoint("suspend",true)
    end
    -- Freeze every home producer before KOReader paints the lock screen. The
    -- visible widget is preserved; normal Home downloads do not own a standby
    -- lease until this Suspend lifecycle has already committed.
    if HomeView.is_shown() and not self:_active_reader_ui() then
        self:_home_freeze_for_suspend()
    end
    if self._download_resume_task then
        UIManager:unschedule(self._download_resume_task)
        self._download_resume_task=nil
    end
    self._reader_interaction_resume_generation=(tonumber(self._reader_interaction_resume_generation) or 0)+1
    if self._reader_interaction_resume_task then
        UIManager:unschedule(self._reader_interaction_resume_task)
        self._reader_interaction_resume_task=nil
    end
    if self._reader_toolbar_state_task then
        UIManager:unschedule(self._reader_toolbar_state_task)
        self._reader_toolbar_state_task=nil
    end
    if self._post_reader_work_task then
        UIManager:unschedule(self._post_reader_work_task)
        self._post_reader_work_task=nil
        HOME_SESSION.post_reader_work_deferred_phase="suspend:"..tostring(HOME_SESSION.post_reader_work_phase or "")
    end
    self:_background_cancel_all("suspend lifecycle",true,false)
    if power_target=="REAL_SUSPEND" then self:_mark_reader_busy(10) end
    -- Normalize the shared download marker last. In beta.12 a concurrent
    -- download remains in PSEUDO_LOCKED/DOWNLOAD_LOCKED while reader_finalizer
    -- holds a separate lease; no reader_finalizer pause reason is injected.
    if self.download_task then
        local download_power_target=self:_passive_prefetch_active() and "REAL_SUSPEND" or power_target
        self.download_task:on_suspend(download_power_target,power.generation)
    end
    self._suspended_at=os.time()
    self:_background_log_state("suspend lifecycle",true)
    logger.info("[MiuRead][Suspend] lifecycle timers cancelled",
        "rebuild=",tostring(reader_rebuild_active()),"rotation=true","resume=true",
        "power=",power_target,"generation=",tostring(power.generation))
    if suspend_sync and type(suspend_sync.on_suspend)=="function" then
        suspend_sync:on_suspend{power_state=power_target,generation=power.generation,
            preserve_final_flush=sync_continue,reading_end_active=sync_continue}
    end
    if PseudoLockscreen.active() then
        -- Kindle beta.4 intentionally does nothing here: powerd remains in its
        -- native screenSaver state until ReadyToSuspend. Kobo's isolated legacy
        -- backend may still use this compatibility hook.
        pcall(PseudoLockscreen.after_suspend)
    end
end
function Plugin:onResume()
    local pseudo_resume=PseudoLockscreen.on_resume_event()
    if pseudo_resume=="hold" then
        -- Compatibility path for a backend that intentionally consumes an
        -- internal resume. Kindle ScreenSaver Hold never returns this value.
        local power=PowerState.transition("PSEUDO_LOCKED","pseudo_internal_resume",{
            download_active=self.download_task and self.download_task:busy() or false,
            download_continue=true,sync_continue=SuspendWorkLease.has("reader_finalizer"),
        })
        self._power_suspend_generation=power.generation
        if self.download_task then
            pcall(self.download_task.on_suspend,self.download_task,"PSEUDO_LOCKED",power.generation)
        end
        logger.info("[MiuRead][Power] internal pseudo-lock resume held",
            "generation=",tostring(power.generation))
        logger.info("[MiuRead][ReadingLifecycle] INTERNAL_WAKE",
            "time=ignored","progress=ignored","annotations=ignored")
        return
    end
    if self._reading_end_standby_held or SuspendWorkLease.has("reader_finalizer") then
        self._reading_end_standby_held=false
        SuspendWorkLease.release("reader_finalizer")
    end
    local previous_power=PowerState.snapshot()
    if self.download_task and type(self.download_task.on_user_resume_begin)=="function" then
        local ok,err=pcall(self.download_task.on_user_resume_begin,self.download_task,PowerState.generation())
        if not ok then logger.warn("[MiuRead][Power] download wake-priority release failed",tostring(err)) end
    end
    self:_reconcile_power_leases("user_resume")
    self._miuread_suspended=false
    HOME_SESSION.suspended=false
    StatusToast.set_blocked(false)
    local close_pending=reader_close_active()
    local native_menu_pending=NATIVE_MENU_GUARD.active==true
    if close_pending then
        self:_set_foreground("reader_transition")
        self:_schedule_reader_return_finish(READER_CLOSE.generation,.25,"resume close watcher")
    elseif native_menu_pending then
        self:_set_navigation_state("native_menu","resume into KOReader menu")
    end
    if self._reader_active_path then U.atomic_write(self._reader_active_path,"1",true) end
    self:_mark_reader_busy(5)
    local slept=self._suspended_at and os.time()-self._suspended_at or 0
    self._suspended_at=nil
    HOME_SESSION.last_resume_clock=monotonic_wall_time()
    local short_wake=slept>0 and slept<(tonumber(Config.SHORT_WAKE_SECONDS) or 5)
    local power=PowerState.transition("RESUMING","onResume",{
        download_active=self.download_task and self.download_task:busy() or false,
        slept=slept,short_wake=short_wake,
    })
    logger.info("[MiuRead][Power] resume transition",
        "from=",tostring(previous_power.state or "-"),"to=RESUMING",
        "generation=",tostring(power.generation),"slept=",tostring(slept),
        "abnormal_short_resume=",tostring(short_wake),
        "previous_download_continue=",tostring(previous_power.download_continue==true))
    self:_power_diagnostic("WakeDiagnostic","RESUMING",
        previous_power.download_continue==true,tostring(previous_power.state or "unknown"))
    UIManager:scheduleIn(.08,function()
        if HOME_SESSION.suspended==true or self._miuread_suspended==true then return end
        HomeData.quick_power_state(true)
        if HomeView.is_shown() and not self:_active_reader_ui() then
            HomeView.update_header{battery_text=self:_home_battery_text()}
        end
    end)
    if HOME_SESSION.return_target=="home" then
        UIManager:scheduleIn(.12,function()
            if HOME_SESSION.suspended==true or self._miuread_suspended==true
                or HOME_SESSION.return_target~="home" or HomeView.is_shown() then return end
            local lifecycle=self:_reader_lifecycle_state()
            logger.warn("[MiuRead][ReaderClose] restoring pending home target after resume",
                "lifecycle=",tostring(lifecycle),
                "session=",tostring(HOME_SESSION.return_session_generation or 0))
            if lifecycle=="active" then
                self:return_to_miuread_home("resume pending home target")
            else
                local generation=self:_begin_reader_return("resume pending home target",
                    HOME_SESSION.return_request_file or HOME_RETURN_FILE,false,
                    HOME_SESSION.return_session_generation)
                self:_schedule_reader_return_finish(generation,.05,"resume pending home target")
            end
        end)
    end
    self:_background_log_state("resume lifecycle",true)
    self:_schedule_frontlight_ui_refresh(.20)
    self._resume_lifecycle_generation=(tonumber(self._resume_lifecycle_generation) or 0)+1
    local resume_generation=self._resume_lifecycle_generation
    local power_generation=power.generation
    UIManager:scheduleIn(math.max(.25,tonumber(Config.POWER_RESUME_QUIET_SECONDS) or 1.0),function()
        if not PowerState.matches(power_generation,"RESUMING")
            or HOME_SESSION.suspended==true or self._miuread_suspended==true then return end
        local normal=PowerState.transition("NORMAL","resume_stable",{
            download_active=self.download_task and self.download_task:busy() or false,
        })
        logger.info("[MiuRead][Power] resume stable",
            "state=",normal.state,"generation=",tostring(normal.generation))
    end)

    local reader_active=self.ui and self.ui.document
    if reader_rebuild_active() then
        if reader_active then
            self:_reader_rebuild_ready_state()
        else
            local owner=READER_REBUILD.owner
            if owner and type(owner._finish_reader_rebuild_candidate)=="function" then
                READER_REBUILD.state="pending"
                local generation=READER_REBUILD.generation
                UIManager:scheduleIn(.35,function()
                    if resume_generation~=self._resume_lifecycle_generation or HOME_SESSION.suspended==true then return end
                    pcall(owner._finish_reader_rebuild_candidate,owner,generation,"resume rebuild re-evaluation")
                end)
            end
        end
    end
    if close_pending then
        self:_ensure_reader_transition_guard("resume during reader close")
        self:_schedule_download_resume_after_wake(3.5)
    elseif native_menu_pending then
        self:_schedule_download_resume_after_wake(3.5)
    end
    if reader_active and not close_pending and not native_menu_pending then
        self:_close_home_for_reader("resume into reader")
        self:_ensure_reader_transition_guard("resume into reader")
        self:_set_foreground("reader")
        UIManager:nextTick(function()
            if self.ui and self.ui.document then
                self:_sync_reader_toolbar_hooks("resume into reader")
            end
        end)
        if self._reader_resume_surface_task then UIManager:unschedule(self._reader_resume_surface_task) end
        -- Kindle may restore its native framebuffer before KOReader repaints.
        -- Wait only until geometry is stable, then repaint the already-open page
        -- once; do not reopen the document or rebuild MiuRead.
        local last_w,last_h,last_rotation,stable,attempts=nil,nil,nil,0,0
        local repaint_task
        repaint_task=function()
            if self._reader_resume_surface_task~=repaint_task then return end
            if resume_generation~=self._resume_lifecycle_generation
                or HOME_SESSION.suspended==true or self._miuread_suspended==true then
                self._reader_resume_surface_task=nil
                return
            end
            attempts=attempts+1
            local sw,sh=Device.screen:getWidth(),Device.screen:getHeight()
            local rotation=Device.screen.getRotationMode and Device.screen:getRotationMode() or nil
            if sw==last_w and sh==last_h and rotation==last_rotation then
                stable=stable+1
            else
                last_w,last_h,last_rotation,stable=sw,sh,rotation,0
            end
            local reader=self:_active_reader_ui()
            if (stable<1 or not (reader and reader.document)) and attempts<7 then
                UIManager:scheduleIn(.12,repaint_task)
                return
            end
            self._reader_resume_surface_task=nil
            if reader and reader.document then
                UIManager:setDirty(reader,"full")
                logger.info("[MiuRead][Power] reader surface repainted after resume",
                    "samples=",tostring(attempts))
            end
        end
        self._reader_resume_surface_task=repaint_task
        UIManager:scheduleIn(.12,repaint_task)
        self:_schedule_download_resume_after_wake(3.5)
        self:_schedule_hibernated_download_resume("resume into reader")
    end
    if not close_pending and not native_menu_pending and not reader_active and HomeView.is_shown() then
        self:_set_foreground("home")
        -- Restore the already-built surface and its input ranges first.  Shelf
        -- refresh, scans, covers and metadata remain behind the interaction
        -- barrier until the page has been released and idle.
        UIManager:nextTick(function()
            if resume_generation~=self._resume_lifecycle_generation
                or HOME_SESSION.suspended==true or self._miuread_suspended==true then return end
            self:_home_begin_resume(slept)
        end)
        UIManager:scheduleIn(1.0,function()
            if HomeView.is_shown() and not self:_active_reader_ui() then
                self:_resume_pending_post_reader_work("resume home",2.0)
            end
        end)
        self:_schedule_hibernated_download_resume("resume home")
        return
    end

    if not close_pending and not native_menu_pending and not reader_active and not HomeView.is_shown() then
        sync_home_session()
        if self:_home_enabled() and HOME_READER_ORIGIN and not HOME_NATIVE_VISIT
            and not HOME_SESSION_SUPPRESSED and not HOME_EXITING then
            self:_set_foreground("home_pending")
            UIManager:scheduleIn(.12,function()
                if not self:_active_reader_ui() and HOME_SESSION.suspended~=true then
                    self:_restore_home_after_reader_close(1)
                end
            end)
        else
            self:_set_foreground("native")
            UIManager:scheduleIn(.05,function() UIManager:setDirty(nil,"ui") end)
        end
        self:_schedule_download_resume_after_wake(3.5)
    end
    if reader_active and not self:_reader_session_is_weread() then
        logger.info("[MiuRead][ReaderSession] resume cloud work skipped",
            "kind=",self:_reader_session_kind(),"slept=",tostring(slept))
        return
    end
    local prefs=self.store:preferences().sync or {}
    local recheck=prefs.pull_on_open~=false and slept>=math.max(60,tonumber(prefs.resume_after) or 300)
    if recheck then
        self._progress_prompted_book_id=nil
        -- Keep the last verified state visible while wake-up revalidation runs.
        -- A transient Wi-Fi delay must not turn a healthy book into an error.
    end
    self.sync:on_resume(slept)
    if recheck then
        self:_wait_for_network("resume-progress",function(ready)
            if ready and self.ui and self.ui.document then
                self:ensure_read_report_progress("resume_recheck",true)
            elseif self.ui and self.ui.document then
                local r=self.sync:record()
                if r then self:_save_progress_state(tostring(r.book.book_id),"waiting_network",
                    "设备已唤醒，等待 Wi-Fi 完全恢复",nil,nil) end
            end
        end,{minimum_delay=6,max_wait=75,interval=3})
    end
end
function Plugin:_post_reader_work_needed()
    local pending=self.store:pending_installs()
    if type(pending)=="table" and #pending>0 then return "install",#pending end
    local queue=self.store:download_queue()
    if type(queue)=="table" and #queue>0 then return "queue",#queue end
    return nil,0
end

function Plugin:_resume_pending_post_reader_work(reason,delay)
    local phase=tostring(HOME_SESSION.post_reader_work_phase or "")
    if phase=="" or self._post_reader_work_task then return false end
    if self:_active_reader_ui() or ReaderTransitionGuard.is_shown() then return false end
    local ok_fm,FileManager=pcall(require,"apps/filemanager/filemanager")
    if not HomeView.is_shown() and not (ok_fm and FileManager and FileManager.instance) then
        return false
    end
    return self:_schedule_post_reader_work(reason or "surface ready",delay or 2.0,phase)
end

function Plugin:_run_post_reader_work(generation)
    if generation~=(tonumber(HOME_SESSION.post_reader_work_generation) or 0) then return false end
    self._post_reader_work_task=nil
    local phase=tostring(HOME_SESSION.post_reader_work_phase or "")
    if self._miuread_suspended==true or HOME_SESSION.suspended==true then
        if phase~="" then HOME_SESSION.post_reader_work_deferred_phase="suspend:"..phase end
        return false
    end
    if phase=="" then
        HOME_SESSION.post_reader_work_deferred_phase=nil
        return true
    end

    local function reschedule(delay)
        local task
        task=function()
            if self._post_reader_work_task~=task then return end
            self._post_reader_work_task=nil
            self:_run_post_reader_work(generation)
        end
        self._post_reader_work_task=task
        UIManager:scheduleIn(math.max(.25,tonumber(delay) or .8),task)
        return false
    end

    if self:_active_reader_ui() or ReaderTransitionGuard.is_shown() then
        -- Do not poll while the user is reading. The next stable home/native
        -- surface or CloseDocument event resumes this exact pending phase.
        if tostring(HOME_SESSION.post_reader_work_deferred_phase or "")~=phase then
            logger.info("[MiuRead][Download] post-reader work deferred until reader closes",phase)
            HOME_SESSION.post_reader_work_deferred_phase=phase
        end
        return false
    end

    -- Returning to the bookshelf is latency-sensitive. Never let install or
    -- queue maintenance run before the page-transition barrier has released.
    if tostring(HOME_SESSION.page_transition_state or "idle")~="idle" then
        if tostring(HOME_SESSION.post_reader_work_deferred_phase or "")~="transition:"..phase then
            logger.info("[MiuRead][Download] post-reader work waiting for transition",phase)
            HOME_SESSION.post_reader_work_deferred_phase="transition:"..phase
        end
        return reschedule(.7)
    end

    local ok_fm,FileManager=pcall(require,"apps/filemanager/filemanager")
    if not HomeView.is_shown() and not (ok_fm and FileManager and FileManager.instance) then
        logger.info("[MiuRead][Download] post-reader work waiting for stable surface",phase)
        return reschedule(.8)
    end
    if HomeView.is_shown() and self:_home_ui_busy() then
        logger.info("[MiuRead][Download] post-reader work yielded to active home",phase)
        return reschedule(.8)
    end

    -- If the user touched the restored home after this work was queued, yield
    -- once more. This prevents a background install/check from stealing the
    -- first interaction after returning from a book.
    local interaction_generation=tonumber(HOME_SESSION.home_interaction_generation) or 0
    local scheduled_generation=tonumber(HOME_SESSION.post_reader_work_interaction_generation) or 0
    if interaction_generation~=scheduled_generation then
        HOME_SESSION.post_reader_work_interaction_generation=interaction_generation
        logger.info("[MiuRead][Download] post-reader work yielded to home interaction",phase)
        return reschedule(1.5)
    end

    HOME_SESSION.post_reader_work_deferred_phase=nil
    local phase_started=monotonic_wall_time()
    if phase=="install" then
        local ok,err=pcall(self._install_pending_downloads,self,true)
        if not ok then logger.warn("[MiuRead][Download] pending install failed",tostring(err)) end
        local queue=self.store:download_queue()
        if type(queue)=="table" and #queue>0 then
            HOME_SESSION.post_reader_work_phase="queue"
            HOME_SESSION.post_reader_work_interaction_generation=tonumber(HOME_SESSION.home_interaction_generation) or 0
            logger.info("[MiuRead][Download] post-reader phase complete",
                "phase=install","ms=",tostring(math.floor((monotonic_wall_time()-phase_started)*1000+.5)),
                "next=queue")
            return reschedule(.8)
        end
        HOME_SESSION.post_reader_work_phase=nil
        logger.info("[MiuRead][Download] post-reader phase complete",
            "phase=install","ms=",tostring(math.floor((monotonic_wall_time()-phase_started)*1000+.5)),
            "next=none")
        return true
    end
    if phase=="queue" then
        local ok,err=pcall(self._start_next_queued_download,self)
        if not ok then logger.warn("[MiuRead][Download] queued start failed",tostring(err)) end
        HOME_SESSION.post_reader_work_phase=nil
        logger.info("[MiuRead][Download] post-reader phase complete",
            "phase=queue","ms=",tostring(math.floor((monotonic_wall_time()-phase_started)*1000+.5)),
            "next=none")
        return true
    end
    HOME_SESSION.post_reader_work_phase=nil
    return true
end

function Plugin:_schedule_post_reader_work(reason,delay,phase)
    phase=tostring(phase or HOME_SESSION.post_reader_work_phase or "")
    if phase=="" then
        local needed=self:_post_reader_work_needed()
        phase=tostring(needed or "")
    end
    if phase=="" then
        HOME_SESSION.post_reader_work_phase=nil
        HOME_SESSION.post_reader_work_deferred_phase=nil
        if self._post_reader_work_task then
            UIManager:unschedule(self._post_reader_work_task)
            self._post_reader_work_task=nil
        end
        logger.info("[MiuRead][Download] post-reader work skipped",tostring(reason or "close"),"nothing pending")
        return false
    end

    HOME_SESSION.post_reader_work_phase=phase
    HOME_SESSION.post_reader_work_deferred_phase=nil
    HOME_SESSION.post_reader_work_interaction_generation=tonumber(HOME_SESSION.home_interaction_generation) or 0
    HOME_SESSION.post_reader_work_generation=(tonumber(HOME_SESSION.post_reader_work_generation) or 0)+1
    self._post_reader_work_generation=HOME_SESSION.post_reader_work_generation
    local generation=self._post_reader_work_generation
    if self._post_reader_work_task then
        UIManager:unschedule(self._post_reader_work_task)
        self._post_reader_work_task=nil
    end
    local task
    task=function()
        if self._post_reader_work_task~=task then return end
        self._post_reader_work_task=nil
        self:_run_post_reader_work(generation)
    end
    self._post_reader_work_task=task
    UIManager:scheduleIn(math.max(0,tonumber(delay) or 2.0),task)
    logger.info("[MiuRead][Download] post-reader work scheduled",tostring(reason or "close"),phase)
    return true
end

function Plugin:onCloseDocument()
    BookExcerptDialog.close("document close")
    local closing_path=normalized_reader_file(self:_current_document_path())
        or normalized_reader_file(HOME_SESSION.reader_session_file)
        or normalized_reader_file(HOME_READER_FILE)
    local opening_path=normalized_reader_file(HOME_SESSION.opening_file)
    local session_generation=tonumber(HOME_SESSION.reader_session_generation) or 0
    local explicit_return=reader_close_active()
        and (self._miuread_return_requested==true or HOME_SESSION.return_requested==true)
    sync_home_session()
    local expected_close=HOME_EXPECTED_CLOSE or HOME_EXITING
        or HOME_SESSION.expected_close==true or HOME_SESSION.exiting==true or UIManager._exit_code~=nil

    -- Preserve a genuine switch target. It is distinct from an unexplained
    -- disappearance of the current ReaderUI.
    local switching_document=opening_path and closing_path and opening_path~=closing_path
    local continuous_switch=switching_document and HOME_SESSION.chapter_switch_active==true
        and normalized_reader_file(HOME_SESSION.chapter_switch_source)==closing_path
        and normalized_reader_file(HOME_SESSION.chapter_switch_target)==opening_path
        and tostring(HOME_SESSION.chapter_switch_book_id or "")==tostring(HOME_SESSION.reader_session_book_id or "")
    if not switching_document and (opening_path==nil or opening_path==closing_path) then
        HOME_SESSION.opening_file=nil
        HOME_SESSION.opening_at=0
    end

    if explicit_return or expected_close then
        if tostring(HOME_SESSION.page_transition_state or "")~="closing_reader" and not expected_close then
            self:_begin_page_transition("closing_reader")
        end
        if not expected_close then self:_ensure_reader_transition_guard("close document") end
        self:_reader_rebuild_cancel("explicit/expected close",true)
        return self:_finalize_reader_instance_close(closing_path,session_generation,
            {explicit_return=explicit_return,reason=expected_close and "expected document close" or "explicit document close"})
    end

    if switching_document then
        self:_reader_rebuild_cancel("explicit document switch",true)
        logger.info("[MiuRead][Lifecycle] document switch observed",
            "old=",tostring(closing_path or ""),"new=",tostring(opening_path or ""))
        return self:_finalize_reader_instance_close(closing_path,session_generation,
            {document_switch=true,continuous_chapter_switch=continuous_switch,
                reason=continuous_switch and "continuous chapter switch" or "document switch"})
    end

    -- No MiuRead/Home request exists. Treat this first as an internal ReaderUI
    -- rebuild candidate and stay out of Home/FileManager lifecycle until KOReader
    -- either returns a Reader or the bounded deadline proves it really closed.
    -- beta.22 deliberately does NOT tear down sync/tap/network state here: that
    -- cleanup belongs to _finalize_reader_instance_close() only after a real
    -- close is confirmed. This keeps same-book reloads cheap and invisible.
    local setting_hint=reader_native_setting_active(closing_path)
    local typography_hint=setting_hint and tostring(READER_NATIVE_SETTING.label or ""):match("^Typography")~=nil
    local tearing_down=self.ui and self.ui.tearing_down==true
    local internal_hint=tearing_down or setting_hint
    logger.info("[MiuRead][Lifecycle] document disappeared","cause=unknown",
        "book=",tostring(closing_path or ""),"session=",tostring(session_generation),
        "tearing_down=",tostring(tearing_down),
        "native_setting=",tostring(setting_hint),"typography=",tostring(typography_hint),
        "setting=",setting_hint and tostring(READER_NATIVE_SETTING.label or "") or "")
    logger.info("[MiuRead][DesktopPerf] reader reload suspected",
        "book=",tostring(closing_path or ""),"internal_hint=",tostring(internal_hint))
    return self:_start_reader_rebuild_candidate(closing_path,session_generation,
        typography_hint and "Typography internal rebuild"
            or (setting_hint and "KOReader native setting rebuild" or "CloseDocument without explicit return"),internal_hint)
end

function Plugin:onFlushSettings()
    self:_mark_ui_preferences_flushed()
    if self._reader_checkpoint_task then
        UIManager:unschedule(self._reader_checkpoint_task)
        self._reader_checkpoint_task=nil
    end
    self:_flush_reader_checkpoint("flush_settings",true)
    self:_flush_cover_index()
    self.store:flush()
end

-- ============================================================
-- 墨痕壁纸屏保：检测 plugins/ 目录下是否有 inkstain 插件
-- 墨痕是独立 KOReader 插件，自行管理屏保设置，miuread 不干预
-- ============================================================
function Plugin:_find_inkstain_plugin()
    -- 优先检查全局实例（插件已加载）
    if _G.InkStainWallpaper then return "loaded" end
    local lfs=require("libs/libkoreader-lfs")
    local search_dirs={}
    local ok_ds,DataStorage=pcall(require,"datastorage")
    if ok_ds and DataStorage then
        local base=DataStorage:getDataDir()
        if base then
            table.insert(search_dirs,base.."/plugins")
            table.insert(search_dirs,base.."/koreader/plugins")
        end
    end
    if #search_dirs==0 then
        table.insert(search_dirs,"./plugins")
        table.insert(search_dirs,"./koreader/plugins")
    end
    for _,dir in ipairs(search_dirs) do
        local main=dir.."/inkstain.koplugin/main.lua"
        if lfs.attributes(main,"mode")=="file" then return main end
        local ok,entries=pcall(lfs.dir,dir)
        if ok and entries then
            for entry in entries do
                if entry:match("inkstain") then
                    local path=dir.."/"..entry
                    local mode=lfs.attributes(path,"mode")
                    if mode=="directory" then
                        local m=path.."/main.lua"
                        if lfs.attributes(m,"mode")=="file" then return m end
                    end
                end
            end
        end
    end
    return nil
end

function Plugin:_inkstain_available()
    if Plugin._inkstain_ok==nil then
        Plugin._inkstain_ok=false
        local ok,path=pcall(Plugin._find_inkstain_plugin,Plugin)
        if ok and path then
            logger.info("[MiuRead][InkStain] found at",path)
            Plugin._inkstain_ok=true
        else
            logger.warn("[MiuRead][InkStain] not found")
        end
    end
    return Plugin._inkstain_ok
end

function Plugin:_inkstain_ensure_or_prompt()
    if self:_inkstain_available() then return true end
    local UIManager=require("ui/uimanager")
    local InfoMessage=require("ui/widget/infomessage")
    local _=require("gettext")
    UIManager:show(InfoMessage:new{
        text=_("墨痕壁纸插件未安装。\n请下载 inkstain 插件，放入 KOReader 的 plugins/ 目录后重启。\n下载地址见 PR 说明或 README。"),
        timeout=5,
    })
    return false
end

return Plugin
